window.HB_TR["1-corinthians"]["ks"]=["1. پالس، یُس خدایہ سٕنزِ مرضی سٍتـ̡ عیسیٰ مسیح سُند رسول، تہٕ سوستھینس {سانہِ} بٲے،\n2. یُس مسیح عیسیٰ مسیحس مَنٛز مقدس چُھ، یُس مسیح عیسیٰ مسیحس مَنٛز مقدس چُھ، یُس پرٮ۪تھ جایہ عیسیٰ مسیح سُند ناو پکاران چُھ، تِمن تہٕ سٲنـ̡ دۅشوے سٍتـ̡ چُھہ یُس عیسیٰ مسیح سُند ناو پکاران چُھ:\n3. خدایہِ سٕندِ باپ سٕندِ طرفہٕ تہٕ خداوند عیسیٰ مسیح سٕندِ طرفہٕ گژھہِ رحمت، تہٕ امن۔\n4. بہٕ چُھس پننہِ خدایہ سُند شُکر ادا کران یُس عیسیٰ مسیح سٕندِ طرفہٕ دِنہٕ آمُت چُھ۔\n5.\\tیہ زِ پریتھ چیزس مَنٛز چھِو تۅہہ سٍتـ̡ تٔمِس سٍتـ̡ مالا مال سپدان تہٕ سارِنٕے علمن سٍتـ̡\n6. یێلہِ زن مسیح سٕنزِ گوٲہی تێہہِ مَنٛز تصدیق سپٕز :\n7. یُتھ زن نہٕ کانہہ تحفہٕ دِتھ پتھ کُن یِن؛ سٲنـ̡ خداوند عیسیٰ مسیح سٕندِ یِنُک انتظار: {یِوان: Gr. Revelation}\n8. یُس تہِ کرِ تۅہہِ ٲخرس تام تصدیق کرُن، {یُتھ زِ تۅہہِ گژھہِ سٲنِس آغہٕ عیسیٰ مسیح سٕندِس دۅہہٕ سٍتـ̡ بے عیب روزُن۔\n9. خدا چُھہ وفادار، ییمہِ سٍتـ̡ یێمہِ سٍتـ̡ تٔمۍ سٕندِس نیچوِس عیسیٰ مسیح سٕندِس رفاقتس مَنٛز بُلاونہٕ آو۔\n10. وۅنۍ چُھس بہٕ تۅہہِ ہٕندِس آغہٕ عیسیٰ مسیح سٕندِ ناوٕ سٍتـ̡ التجا کران زِ تُہۍ سارِوٕے کٔرِو اَکی کتھ کٔرِتھ، تہٕ یێلہِ گژھہِ نہٕ تُہٕندِس درمِیان کانہہ اختلاف سپدُن۔ مگر {یہ} تۅہہ گژھِو اکۍ سے ذہنس منز تہٕ اکۍ سے فٲصلس منز مکمل طور رٔلِتھ۔ {تقسیم: Gr. Schisms}\n11. تکیازِ میہ چھہ یہ اعلان کرنہ آمت زِ تۅہہ چھہ میہ کُن اعلان کورمُت زِ تۅہہ چھہ کلوو سٕندِس گرس منز تہِ اختلاف سپدان۔\n12. وۅنۍ چُھس بہٕ یہِ ونان زِ ژے منزٕ پرٮ۪تھ کانہہ چُھس ونان زِ بہٕ چُھس پولس سُند ۔ تہٕ I، اپولوس؛ تہٕ I سیفاس؛ تہٕ میہ مسیح سُند۔\n13. کیا مسیح چُھ تقسیم گومُت؟ پولس اوسا ژےٚ خٲطرٕ مصلوب کرنہٕ آمُت؟ یا اوسُکھ پولس سٕندِ ناوٕ سٍتـ̡ بپتسمہ دِنہٕ آمُت؟\n14. بہٕ چُھس خدایہِ سُند شُکر ادا کران زِ مے چُھہ نہٕ تۅہہ منزٕ کٲنسہ تہِ بپتسمہ دِژمُت، مگر کرسپس تہٕ گیئس۔\n15. یێلہِ گژھہِ کٲنسہِ یہ ونُن زِ میہ اوس پننِس ناوس پیٹھ بپتسمہ دِژمُت۔\n16.\\tتہٕ مے دِژ سٹیفناس سٕندِس گرس تہِ بپتسمہ دِنہٕ: امہِ علاوٕ چھُنہٕ میہ پتاہ زِ مے کٔر بییہ کٲنسہِ بپتسمہ دِنہٕ۔\n17. تکیازِ مسیحن اوس نہ میہ بپتسمہ دِنہٕ خٲطرٕ بلکہ انجیل ہنز تبلیغ کرنہٕ خٲطرٕ سوزمُت: لفظن ہٕنزِ دانٲیی سٍتـ̡ نہٕ، یُتھ زن مسیح سُند صلیب گژھہِ نہٕ کانہہ اثر سپدِ۔ {الفاظ: یا، تقریر}\n18. تِکیازِ صلیب سٕنز تبلیغ چُھ تِمن ہٕندِ خٲطرٕ یِم بیوقوفی ہُند خاتمہ سپدان چھِ۔ مگر اسہِ خٲطرٕ یُس نجات دِنہٕ آمُت چُھ، سُہ چُھ خدایہِ سُند طاقت۔\n19.\\tیِہ چُھہ لیکھنہٕ آمُت، بہٕ کرٕ دانشمندن ہٕنز حکمت تباہ تہٕ ہوشیار سٕنز سمجھ کُنہِ تہِ کُنہِ تہِ کُنہِ تہِ کُنہ\n20.\\tدانشمند کتہِ چھہِ؟ کاتب کتہِ چھُ؟ یَتھ دُنیاہُک تنازعہ کَتہِ چھُ؟ کیا خداین چھہ نہ یتھ دنیاہچ حکمت بیوقوف بنٲومژ؟\n21. تِکیازِ امہِ پَتہٕ خدایہِ سٕنزِ حکمتہٕ سٍتـ̡ اوس نہٕ دنیاہس خدایہِ سٍتـ̡ زانان ، یێلہِ سٍتـ̡ خدایہِ سٍتـ̡ تبلیغ کرنہٕ سٍتـ̡ خدایہ خوش گٔیہِ۔\n22.\\tیہودین خٲطرٕ چُھ نشانہٕ درکار تہٕ یونانۍ چھِ حکمت ژھاران۔\n23. مگر أسـ̡ چِھہ مسیحس مصلوب کٔرِتھ تبلیغ کران، یہودین ہٕندِ خٲطرٕ تہٕ یونانین ہٕنزِ بیوقوفی ہٕنز تبلیغ کران۔\n24.\\tمگر یِمن یہودی تہٕ یونانۍ دۅشوے ونان چھِ، مسیح خدایہِ سٕنز طاقت تہٕ خدایہِ سٕنز حکمت۔\n25.\\tکیازِ خدایہ سنز حماقت چھیہ انسانو کھوتہ زیادہ عقلمند۔ تہٕ خدایہِ سٕنز کمزوری چھے انسانو کھوتہٕ زیادٕ مضبوط۔\n26. تِکیازِ تُہۍ چھِو پنٕنۍ بلاوے وُچھان، بٲے زِ ماز پَتہٕ کِتھہ پٲٹھۍ، واریاہ طاقتور نہٕ، واریاہ رٔٹِھ، {چُھہ وننہٕ آمُت}:\n27. مگر خداین چُھ دنیاہٕچ بیوقوف چیزن ہُند انتخاب کرمُت یُس عقلمند پریشان کرنہٕ خٲطرٕ چُھ۔ تہٕ خداین چُھ دنیاہٕچ کمزور چیزن ہُند انتخاب کوٚرمُت یُس طاقتور چیزن ہُند الجھاونہٕ مۅکھٕ چُھ۔\n28.\\tتہٕ دنیاہٕکۍ بُنیٲدی چیز، تہٕ یِمن چیزن ہٕنز حقارت چھِ کرنہٕ آمٕژ، تہٕ یِم نہٕ چھِ، تِمن چیزن ہُند انتخاب کٔرِتھ یِم نہٕ چھِ:\n29.\\tزِ کانہہ تہِ ماز گژھہِ نہ تسنزِ حضوری سٍتـ̡ جلال سپدُن۔\n30. مگر تُہۍ چھِو مسیح عیسیٰ مسیحس مَنٛز، یُس خدایہِ سٕندِ طرفہٕ اسہِ خٲطرٕ حکمت، نیکی تہٕ پاکیزگی تہٕ نجات دِنہٕ آمُت چُھ:\n31.\\tیُس لیکھنہٕ آمُت چُھ، یُس جلال دِوان چُھ، سُہ گژھہِ خداوند سٕندِس جلال سٍتـ̡ جلال دِنہٕ۔","1. تہٕ بہٕ، بھائیو، ییلہ بہٕ ژےٚ نِش آو، تہٕ بہٕ آو نہٕ خدایہِ سٕنز گوٲہی دِنہٕ سٍتـ̡ تہٕ کتھ باتھہِ ہٕندِس سٍتـ̡ تہٕ حکمت ہٕندِ سٍتـ̡ ۔\n2. تکیازِ میہ چھہ تہِ ارادہ کوٚرمت زِ عیسیٰ مسیح سٍتـ̡ تہٕ سُہ آو صلیب دِنہٕ۔\n3. تہٕ بہٕ اوسُس ژےٚ سٍتـ̡ کمزوری، خوفس منز، تہٕ وارِیاہ تھرتھرس منز۔\n4. تہٕ میون کلام تہٕ تبلیغ ٲس نہٕ انسان سٕنزِ حکمت ہٕندِس دلکش کلامس سٍتـ̡ بلکہ روح تہٕ طاقتہٕ کِس مظٲہرس منز: {لالچ: یا، قائل کٔرِتھ}\n5. زِ تُہند ایمان گژھہِ نہ انسانن ہٕنزِ حکمتس مَنٛز بلکہ خدایہ سٕندِس طاقتس مَنٛز کھڑا آسُن۔ {سٹینڈ: Gr. be}\n6. یێلہِ تہِ أسۍ تِمن مَنٛز حکمتٕچ کتھ کران یِم کامل چھِ: توتہِ چھُنہٕ یتھ دنیاہٕچ حکمت، تہٕ نہ یتھ دنیاہٕکۍ شہزادن ہٕنز، یُس ناکام سپدان چھُ:\n7. مگر أسۍ چھِ خدایہ سٕنز حکمت أکِس اسرارس مَنٛز کتھ کران، {حتیٰ کہ} پوشیدٕ {حکمت}، یُس خداین دُنیاہس برونہہ کُن سٲنِس جلال خٲطرٕ مقرر کورمُت چھُ:\n8.\\tیُس نہ امہ دنیاہٕکۍ شہزادن منز کانہہ تہِ پتاہ اوس، تکیازِ اگر تِمن پتاہ آسہِ ہے نہٕ تِمو جلال کِس مالہِ سُند صلیب دِنہٕ۔\n9. مگر یِتھ کٔنۍ چُھ لیکھنہٕ آمُت زِ أچھ چُھ نہٕ وُچھمُت، تہٕ کَن چُھہ بوزمُت، تہٕ چُھہ نہٕ انسان سٕندِس دِلس مَنٛز دٲخل گٔمٕتۍ، یِم خداین تِمن ہٕندِ خٲطرٕ تیار کٔرۍمٕتۍ چھِ۔\n10. مگر خداین کٔر اسہِ خٲطرٕ پننہِ روحہٕ سٍتـ̡ ظٲہر کرنہٕ، تکیازِ روح چُھ سارِنٕے چیزن ہٕنز تلاش کران، ہاں، خدایہِ سٕنزِ سرٛوٚن چیز۔\n11.\\tتکیازِ انسان کُس انسان چھہ انسان سٕنزِ چیزن زانان، سوائے انسان سٕندِ روح یُس تس منز موجود چھُ؟ توتہِ چُھہ خدایہ سٕندِ چیزس کانہہ تہِ انسان زانان، مگر خدایہ سُند روح۔\n12. وۅنۍ چُھہ اسہِ دنیاہُک روح نہٕ بلکہ خدایہ سُند روح میلیومُت۔ یُتھ زن أسۍ تِم چیز زانِتھ یِم اسہِ خدایہِ سٕندِ طرفہٕ آزادانہ طور دِنہٕ آمٕتۍ چھِ۔\n13. کُس چیز تہِ چھہِ اسۍ کتھ کران، نہ تمن لفظن منز یم انسان سنز حکمت ہیچھناوان چھہِ، بلکہ یُس روح القدس ہیچھناوان چھُ۔ روحٲنی چیزن ہُند موازنہٕ روحٲنی سٍتـ̡ کرُن۔\n14. مگر فطری انسان چُھ نہٕ خدایہ سٕندِ روحہٕ سٕندِ چیزن ہٕندِس سٍتـ̡ رٔٹِتھ، تِکیازِ تِم چِھہ أمِس خٲطرٕ بیوقوف: تہٕ نہ ہیکہِ سُہ زانِتھ، تِکیازِ تِم چِھ روحٲنی طور سمجھنہٕ آمٕتۍ۔\n15. مگر یُس روحانی چُھ سارِنٕے چیزن ہُند فیصلہ کران، توتہِ چُھہ نہٕ تس پانہٕ کٲنسہِ انسانس سٍتـ̡ فیصلہ کرنہٕ آمُت۔{Judgeth: or, Discerneth} {Judge: or, Discerneth} {Judge: or, Discerneth}\n16.\\tکیازِ کُس چُھ خداوند سُند ذہنس زانان تہٕ سُہ کرِ أمِس ہدایت دِنہٕ؟ مگر اسہِ چُھ مسیح سُند ذہن۔ {مے: Gr. shall}","1. تہٕ بہٕ ہیوٚک نہٕ توے سٍتـ̡ روحٲنی سٍتـ̡ کتھ کٔرِتھ، بٔلکہِ جسمٲنی سٍتـ̡ کتھ کٔرِتھ، یێلہِ زن عیسیٰ مسیحس مَنٛز بچن سٍتـ̡ کتھ کٔرِتھ۔\n2. مے چُھہ ژے دۄد دِژمُت، تہٕ ماز سٍتـ̡ نہٕ، تِکیازِ تۅہہ ٲسِو نہٕ وُنہِ تہِ قٲبل۔\n3.\\tتکیازِ تۅہہِ چھِو وُنہِ تہِ جسمانی: ییلہ زن تۅہہِ منز حسد تہٕ کشمکش تہٕ تقسیم چھِ، کیا تۅہہ چھِو نہٕ جسمٲنی طور پکان تہٕ مردن ہٕندۍ پٲٹھۍ؟ {تقسیم: یا، فرقہٕ} {بطور مرد: Gr. مطابق انسان؟}\n4. یێلہِ زن اکھ وَنُن چُھ، بہٕ چُھس پولس سُند۔ تہٕ بیاکھ ، بہٕ چُھس اپولوسُک {am}؛ کیا تُہۍ چھِو نہٕ جسمٲنی ؟\n5. تیلہِ کُس چُھ پولس تہٕ کُس چُھہ اپولوس، مگر تِم خادم یِمن سٍتـ̡ تۅہہ پژھ تھاوان چُھ، یِتھٕ پٲٹھـ̡ خداوند پریتھ انسانس دِژمُت؟\n6. مے چُھ پودٕ لگٲومُت، اپولوسن آب دِژمُت۔ مگر خداین دیت ہُریر۔\n7. تیلہِ چُھ نہٕ سُہ یُس کانہہ چیز ووپداوان چُھ، تہٕ نہ چُھ سُہ آب دِوان۔ مگر خدایہ یُس اضافہٕ دِوان چھُ۔\n8.\\tیُس ووپداوُن چُھہ تہٕ یُس آب دِوان چُھ، سُہ چُھ اَکہٕ سٍتـ̡ تہٕ پرٮ۪تھ أکِس انسانس میلہِ پننہِ محنتہٕ مُطٲبق۔\n9. تکیازِ أسۍ چھہِ خدایہ سٍتـ̡ رٔلِتھ مزدور: تہۍ چھِو خدایہِ سٕنز رچھن، تہٕ تہٕ چُھہ خدایہِ سٕنز عمارت۔ {رچھن: یا، کاشت}\n10. خدایہ سٕندِ فضل مطٲبق یُس میہ دِنہٕ آمُت چُھ، أکِس عقلمند ماسٹر بلڈر سٕندِ حثیتہٕ چُھہ مے بُنیاد تھوومُت، تہٕ بیاکھ چُھ اتھ پیٹھ تعمیر کران۔ مگر پریتھ انسان گژھہِ دھیان زِ سہ کتھہ پاٹھۍ چھہ اتھ پیٹھ تعمیر کران۔\n11. یێمہِ بُنیادٕ سٍتـ̡ ہێکہِ نہٕ کانہہ تہِ انسان ترٲوِتھ یُس عیسیٰ مسیح چُھ۔\n12.\\tوۅنۍ اگر کانہہ انسان اتھ بنیادس پیٹھ سون، رۄپھ، قیمتی پتھر، لٔکر، گاسہ، گاسہ بناوان آسہِ۔\n13.\\tپریتھ انسان سٕنز کٲم گژھہِ ظٲہر کرنہٕ: تکیازِ دۅہہ گژھہِ امیک اعلان کرنہٕ، تکیازِ یہ گژھہِ نارٕ سٍتـ̡ ظٲہر کرنہٕ۔ تہٕ نار کرِ پرٮ۪تھ انسان سٕنزِ کامہِ ہٕنز کوشش کٔرِتھ زِ یہِ کُنہِ قسمُک چُھ۔ {یہ آسہِ: Gr. it}\n14.\\tاگر کٲنسہِ انسان سٕنز کٲم یُس تٔمِس بنوومُت آسہِ، تٔمِس میلہِ اَمہ سٍتـ̡ ثواب میلہٕ۔\n15.\\tاگر کٲنسہِ شخصہٕ سٕنز کٲم زالنہٕ ییہِ، تٔمِس گژھہِ نۄقصان، مگر سُہ گژھہِ پانہٕ نجات دِنہٕ۔ توتہِ چھہ نارس سیتۍ تہِ۔\n16. کیا تۅہہ چھے نہٕ پتاہ زِ تہٕ چُھہ خدایہِ سُند مندر تہٕ یُس خدایہِ سُند روح چُھہ توے مَنٛز روزان؟\n17. یێلہِ کانہہ انسان خدایہ سٕندِس مندرس ناپاک کرِ، سُہ کرِ خدایہ برباد۔ تکیازِ خدایہ سُند مندر چُھ مُقدس، یُس {مندر} چُھہ تُہۍ چھِو۔ {ناپاک: یا، تباہ کٔرِو}\n18.\\tکانہہ تہِ انسان گژھہِ نہ پانس دھوکہ دِتھ۔ اگر تۄہہِ منزٕ کانہہ انسان یتھ دنیاہس منز عقلمند باسان آسہِ، سُہ گژھہِ بیوقوف بنُن، یُتھ سُہ عقلمند بٔنِتھ۔\n19. یێمہِ دنیاہٕچ حکمت چھے خدایہِ سٍتـ̡ بیوقوفی ۔ تکیازِ یہ چھہ لیکھنہ آمت زِ سہ چھہ دانشمندن پننہِ چالاکی منز رٹان۔\n20. تہٕ بییہِ چُھہ خداوند دانشمندن ہٕندِس خیالس زانان زِ تِم چِھ بیکار۔\n21. لہذا گژھہِ نہ کانہہ انسان انسانس پیٹھ فخر کرُن۔ سارِنٕے چیٖز چھِ تُہٕندِ؛\n22. چاہے پولس، یا اپولوس، یا سیفاس، یا دنیا، یا زندگی، یا موت، یا موجودٕ چیز، یا یِنہٕ وٲلِس چیز۔ سٲری چھہِ تۅہہ؛\n23. تہٕ تُہۍ چھِو مسیح سٕندِ۔ تہٕ مسیح چُھ خدایہِ سُند۔","1. یێلہِ سٍتـ̡ اسہِ سٍتـ̡ عیسیٰ مسیح سٕندِس وزیرن تہٕ خدایہِ سٕندِس اسرارن ہٕندِس نگرٲنی سٍتـ̡ گژھہِ اسہِ سٍتـ̡ حساب دِنہٕ۔\n2. امہ علاوہ چھہ یہ ضروری زِ انسان گژھہِ وفادار لبنہٕ یُن۔\n3.\\tمگر میانہِ سٍتۍ چھہ یہ سیٹھا لۅکٹ کتھ زِ میہ گژھہِ ژے یا انسان سندِ فٲصلس پیٹھ فیصلہ کرنہ یُن: آ، بہٕ چھُس نہ پننس پانس فیصلہ کران۔ {فیصلہ: Gr. Day}\n4. کیازِ بہٕ چُھس نہٕ پانہٕ کانہہ تہِ زانان۔ توتہِ چُھس نہٕ بہٕ یَتھ سٍتـ̡ انصاف دِنہٕ آمُت: مگر یُس میہ فیصلہ کران چُھ، سُہ چُھ خداوند ۔ {زانِتھ: یا، بہٕ چُھس نہٕ کُنہِ تہِ غلطی ہُند احساس}\n5.\\tتێلہِ کرو نہٕ وقتس برونہہ کُنہِ تہِ فیصلہٕ، یوتام نہٕ خداوند یِن، یُس دۅشوے اندھیرِ ہٕندِس پوشیدٕ چیزن ہُند ظٲہر کرِ، تہٕ دلن ہٕنزِ نصیحت ظٲہر کرِ، تہٕ تێلہِ گژھہِ پریتھ انسانس خدایہ سُند حمد کرنہٕ۔\n6. تہٕ یِم چیز، بھائیو، مے چُھس أکِس شکلہٕ سٍتـ̡ پانس تہٕ اپولوس کُن منتقل کورمُت۔ تاکہ تۅہہ گژھہِ اسہِ منز ہیچھِتھ زِ یُس لیکھنہٕ آمُت چھُ، تہٕ یُس نہٕ تۅہہ منزٕ کانہہ تہِ اکھ أکِس خلاف دِنہٕ یُن۔\n7. تکیازِ کُس چُھہ ژیہ بییِس نِش مختلف بناوان؟ تہٕ ژے کیا چُھہ یُس نہٕ ژے رٔٹِتھ چُھہ؟ وۅنۍ اگر ژیہ میلہِ، تیلہِ کیازِ چھکھ ژیہ جلال کران، گویا نہ یہ میلہِ۔ {maketh...: Gr. distinguishe}\n8.\\tوۅنۍ چھکھ ژیہ پورمُت، وۅنۍ چھکھ امیر، تہٕ بہٕ چھُس خدایہ سٍتـ̡ بادشاہ کٔرِتھ تہٕ أسـ̡ تہِ کرو ژے سٍتـ̡ بادشاہ۔\n9. تکیازِ بہٕ چُھس باسان زِ خداین چُھ اسہِ رسولن پٔتِم مقرر کورمُت، یِتھ کٔنۍ زِ أسـ̡ چُھہ دُنیاہس تہٕ فرشتن تہٕ انسانن ہٕندِ خٲطرٕ اکھ تماشہٕ بناونہٕ آمُت۔ {اسہِ...: یا، اسہِ ٲخری رسول، as} {تماشہٕ: Gr. Theatre}\n10. أسۍ چھِ مسیح سٕندِ خٲطرٕ بیوقوف، مگر تُہۍ چھِو مسیحس مَنٛز دانشمند۔ أسۍ چھِ کمزور، مگر تُہۍ چھِو مضبوط۔ تُہۍ چھِو عزت، مگر أسۍ چھِ نفرت۔\n11.\\tاز تام تہِ چھہِ اسۍ دۅشوے فاقہ، تہ ترش، ننگہ، تہ بٹہ چھِ، تہٕ چھِنہٕ کانہہ خاص روزنٕچ جاے آسان۔\n12. تہٕ محنت، پننیو اتھو سٍتـ̡ کٲم کٔرِتھ: ملامت کٔرِتھ أسـ̡ برکت دِوان۔ ستاونہٕ یِنہٕ سٍتـ̡ أسـ̡ أسـ̡ سٍتـ̡ دِنہٕ آم\n13.\\tبدنام سپدِتھ چھِ أسۍ دُنیاہُک گندٕ بناونہٕ آمٕتۍ، {تہٕ چھِ} از تام سارِنٕے چیزن ہٕندِس کُنہِ کُنہِ سٍتـ̡ دِنہٕ آمٕتـ̡ ۔\n14.\\tبہٕ چھُس نہٕ یِم کتھٕ ژےٚ شرمندٕ کرنہٕ خٲطرٕ لیکھان بلکہ چھُس پننین پیارے نیچوین ہٕندِ حثیتہٕ خبردار کران {ژے}۔\n15. یێلہِ تہِ چُھہ عیسیٰ مسیحس مَنٛز دَہ ساس ہیچھناوُن، توتہِ چُھہ نہٕ تۅہہِ واریاہ باپ، تکیازِ عیسیٰ مسیحس منز چُھہ ژے انجیل سٍتـ̡ پٲدٕ کورمُت۔\n16. اَمہِ مۄکھٕ چُھس بہٕ ژےٚ گُزٲرِتھ زِ تُہۍ بٔنِو میانہِ پٲروکار۔\n17. اَمہِ مۅکھہٕ چُھہ مے تۅہہِ نِش تیموتھیس سوزمُت، یُس میون ٹٲٹھ نیچو چُھ، تہٕ خداوند سُند وفادار چُھ، یُس ژے میٲنۍ وتہٕ یاد پاونہٕ یُس مسیحس مَنٛز چُھ، یِتھ کٔنۍ بہٕ پرٮ۪تھ کُنہِ کلیساہس مَنٛز پرٮ۪تھ جایہِ ہیچھناوان چھُ۔\n18.\\tوۅنۍ چھہِ کینہہ پھپھ کٔرتھ، زن بہٕ ییہ نہ ژیہ نِش۔\n19. مگر بہٕ ییہ جلدٕے ژے نِش، یێلہِ خداوند ییہِ تہٕ زانہِ تِمن ہٕنزِ کتھ یِم پھۅپھ کٔرِتھ چھِ، بٔلکہِ طاقت۔\n20. تکیازِ خدایہ سٕنز بادشٲہی {چُھ} لفظس منز نہٕ بلکہ طاقتس منز۔\n21. تُہۍ کیا کرِو؟ بہٕ واتہٕ ژے نِش لٔرۍ، یا محبتہٕ سٍتۍ، تہٕ نرمی ہٕندِس جذبس سٍتۍ؟","1.\\tعام طور چھہ یہ وننہ یوان زِ تۅہہِ منز چھہ زناکاری سپدان تہ یُتھ زنا چھہ نہ غیر قومن منز یُس ناو آسہِ، تہ تس گژھہِ مٲلۍ سنز زنانہ آسن۔\n2. تہٕ تُہۍ چھِو پھۅپھ کٔرِتھ، تہٕ بٔلکہِ چُھکھ نہٕ ماتم کٔرِتھ، یُس یہِ کٲم کٔرمٕژ آسہِ، یُس تہٕ یُس یہِ کٲم کٔرمٕژ آسہِ، یُس تہٕ یُس تہِ کٔرِتھ آسہِ۔\n3.\\tکیازِ میہ چھہ پزۍ پاٹھۍ جسمس منز غیر حاضر مگر روحس منز موجود، گوڈہ فیصلہ کورمُت، گویا بہٕ موجود اوسس، تٔمِس متعلق یمۍ یہ کٲم کٔرمٕژ، {فیصلہٕ: یا، طے کورمُت}\n4. سٲنـ̡ خداوند عیسیٰ مسیح سٕندِ ناوٕ سٍتـ̡ ییلہ تم یکوٹہ جمع سپدِو، تہٕ میانہِ روحہٕ، سٲنـ̡ خداوند عیسیٰ مسیح سٕندِ طاقتہٕ سٍتـ̡\n5.\\tیُس یُس شیطانس تام واتناوُن یُس ماز ہٕندِ تباہی خٲطرٕ واتناوُن، یُتھ خداوند عیسیٰ سٕندِ دۅہہٕ گژھہِ روح نجات دِنہٕ۔\n6.\\tتہنز عظمت چھیہ نہ اصل۔ ژیہ چھیہ نہ پتاہ زِ رژھ کھنڈ خمیر چھہ سورے گٹہِ سیتۍ واٹھ دوان۔\n7. تَمہِ مۄکھٕ کٔرِو پرٛون خمیر صاف کٔرِتھ، یُتھ زن تُہۍ چھِو خمیرٕ روٚس۔ مسیح سٕندِ خٲطرٕ تہِ چُھ سون فسح سانہِ خٲطرٕ قربان کرنہٕ آمُت: {چُھ قربان کرنہٕ آمُت؛ یا، چُھ مارنہٕ آمُت}\n8.\\tلہذا کرو اسہِ دعوت مناون، نہ پرانہِ خمیرس سٍتۍ، نہ بد خواہی تہٕ بدکاری سٍتۍ۔ بلکہ اخلاص تہٕ سچائی ہٕندِس بے خمیر {روٹی} سٍتۍ۔ {دعوت: یا، مقدس دوہ}\n9.\\tمیہ لیوکھمُت ژے أکِس خطس منز زنا کرن والٮ۪ن سٍتـ̡ صحبت:\n10.\\tتوتہِ چھُنہٕ پوٗرٕ پٲٹھۍ یِتھ دُنِیاہٕکِس زناکارَن سٍتۍ، یا لالچَن سٍتـ̡ یا مشرکَن سٍتـ̡ ۔ تکیازِ تیلہ گژھہِ ژیہ دنیا نیبر نیرُن۔\n11.\\tمگر وۅنۍ چُھس مے ژےٚ لیوٗکھمُت زِ اگر کانہہ نفر یُس بٲے ونان چھُ، سُہ آسہِ نہٕ زناکار، یا لالچ، یا مشرک، یا شرابہ، یا بھتہ خور آسہِ۔ یِتھِس نہٕ کھٮ۪نہٕ یِنہٕ وٲلِس سٍتۍ۔\n12.\\tمیہ کیا کرُن تمن ہند فیصلہ کرنہٕ خٲطرٕ یُس امہِ ورٲے چھُ؟ کیا تُہۍ چھِو نہٕ تِمن ہُند فیصلہ کران یِم اندر چھِ؟\n13.\\tمگر یُس خدایہ سٍتـ̡ بێیہِ چُھہ فیصلہ کران۔ تَمہِ مۄکھٕ کٔرِو سُہ بدکار شخٕص پانَس نِش دوٗر کٔرِتھ۔","1.\\tتوہہِ منزٕ چھا کٲنسہِ ہُند ہمت زِ یُس بییِس خلاف معاملہٕ آسہِ، سُہ گژھہِ ناانصافن برونہہ کُن قانونس برونہہ کُن گژھُن، تہٕ نہ کہ مقدسن برونہہ کُن؟\n2. کیا تۅہہ چھے نہٕ پتاہ زِ مقدس کرن دنیاہُک فیصلہٕ؟ تہٕ اگر دنیاہُک فیصلہ ژے کرِ، کیا تُہۍ چھِو نہٕ لۄکٹٮ۪ن معاملن ہُند فیصلہ کرنس لایق؟\n3. ژیہ چھے نہٕ پتاہ زِ أسۍ کرو فرشتن ہُند فیصلہٕ؟ اتھ زندگی سٍتۍ کٲژاہ چیز چھہِ؟\n4. یێلہِ تێلہِ چُھہ یێلہِ زِندگی مُتلق چیزن ہُند فیصلہٕ چُھ، تێلہِ تھٲوِو تِمن فیصلن ہٕندِ خٲطرٕ مقرر یُس کلیساہس مَنٛز کم از کم احترام چُھ۔\n5. بہٕ چُھس چانہِ شرمندگی ہنز کتھ کران۔ کیا یہِ چھُنہٕ تۅہہِ مَنٛز کانہہ عقلمند شخص؟ نہ، کانہہ تہِ یُس پننین باین درمیان فیصلہ کرِ؟\n6. مگر بٲے چُھ بٲے سٍتـ̡ شریعت کُن گژھان، تہٕ سُہ چُھ کافرن برونہہ کُن۔\n7. تێمہِ کِنۍ چُھ تۅہہِ مَنٛز سراسر غلطی، تکیازِ تُہۍ چھِو اَکھ أکِس سٍتـ̡ شریعت کُن گژھان۔ تۅہہ کیازِ چھِو نہٕ غلط سمجھان؟ تۅہہ کیازِ چھِو نہٕ پانس دھوکہٕ دِنہٕ خٲطرٕ دِوان؟\n8. نہ، تُہۍ چھِو غلط کران تہٕ دھوکہ دِوان، تہٕ سُہ {پنُن} بٲے۔\n9.\\tژیہ چھے نہٕ پتاہ زِ بدکار گژھن نہٕ خدایہ سٕنزِ بادشٲہی ہُند وارث۔ دھوکہ دِنہٕ یِن: نہ زناکار، نہ مشرک، نہ زناکار، نہ زناکار، نہ انسانس سٍتـ̡ پانس سٍتـ̡ زیادتی کرُن،\n10. نہ چور، نہ لالچ، نہ شرابہ، نہ بدکار تہٕ نہ جبر کرن وٲلۍ، خدایہ سٕنزِ بادشٲہی ہُند وٲرث۔\n11. تہٕ یِتھٕ کُنہِ تہِ ٲسِو، مگر یێلہِ چُھہ واش کرنہٕ آمُت، مگر تُہۍ چھِو خداوند عیسیٰ سٕندِ ناوٕ سٍتـ̡ تہٕ سٲنِس خدایہ سٕندِ روحہٕ سٍتـ̡ پابند سپدان۔\n12.\\tسٲری چیز چھہِ میانہِ خاطرہ حلال مگر سٲری چیز چھہِ نہ مصلحت: سٲری چیز چھہِ میانہِ خاطرہ حلال مگر بہٕ گژھہِ نہ کٲنسہِ ہٕندِس اختیارس تل اننہٕ۔ {مصلحت: یا، نفع بخش}\n13. یٔڈ خٲطرٕ ماز، تہٕ یٔڈ مازٕ خٲطرٕ، مگر خدا کرِ یہِ تہٕ تِمن دۄشوٕے تباہ کرنہٕ۔ وۅنۍ چُھ جسم زنا کرنہٕ خٲطرٕ نہٕ بلکہ خداوند سٕندِ خٲطرٕ۔ تہٕ خداوند جسمہٕ خٲطرٕ۔ {ماز: نہ صرف ماز، بلکہ کُنہِ تہِ قٕسمُک کھیٛن}\n14. تہٕ خداین چُھ خداوند تُلمت تہٕ کرِ اسہِ پننہِ طاقتہٕ سٍتـ̡ زندٕ۔\n15. کیا تُہۍ چھِو نہٕ پتاہ زِ تُہند جسم چُھ مسیح سٕندِ رُکُن؟ تیلہِ کیا بہٕ مسیح سٕندِ ارکان نِتھ، تہٕ یِمن بَناوٕ أکِس فاحشہٕ سٕندِ رُکُن؟ خدا نہ کرِ۔\n16. کیا؟ ژیہ چھے نہ پتاہ زِ یُس بدکار سٍتۍ رٔلِتھ چھُ، سُہ چھہ اکھ جسم؟ دۅن خٲطرٕ، سُہ چُھ ونان زِ اکھ ماز آسہِ۔\n17. مگر یُس خداوند سٍتـ̡ رٔلِتھ چُھہ سُہ چُھ اَکھ روح۔\n18. زناکاری نِش ژلُن۔ انسان سُند پرٮ۪تھ کانہہ گۅناہ چُھ سُہ چُھ جسمہٕ ورٲے آسان۔ مگر یُس زنا کران چُھ، سُہ چُھ پننِس جسمس خلاف گناہ کران۔\n19. کیا؟ ژیہ چھے نہٕ پتاہ زِ تُہند جسم چُھ روح القدس سُند مندر {یُس توے منز} چُھ، یُس تۅہہِ خدایہِ سٕندِ طرفہٕ چُھ، تہٕ تُہۍ چُھہ نہٕ پنُن پنُن؟\n20. تِکیازِ تُہۍ چھِو أکِس قٲمتس سٍتـ̡ ہینہٕ آمٕتۍ، تێمہِ مۄکھٕ کٔرِو پننِس جسمس مَنٛز تہٕ پننِس روحس مَنٛز خدایہِ سٕنز حمد کٔرِو، یُس خدایہِ سُند چُھ۔","1.\\tوۅنۍ تمن چیزن متعلق، یمن متعلق ژیہ میہ لیوکھمُت چھُ: مردس خٲطرٕ چُھ نہٕ زنانہِ اتھہٕ لاگُن اصل۔\n2. بہر حال، زناکاری نِش بچنہٕ خٲطرٕ، گژھہِ پریتھ مردس پنٕنۍ زنانہٕ آسٕنۍ، تہٕ پرٮ۪تھ زنانہِ گژھہِ پنُن خانٛدار آسُن۔\n3.\\tخاوند گژھہِ زنانہِ سٍتـ̡ احسان دِنـ̡ تہٕ یِتھٔے پٲٹھـ̡ خانٛدارِنہِ تہِ دِیہِ۔\n4.\\tزنانہِ چھہ نہ پننس جسمس پیٹھ اختیار تھاوان، بلکہ خاوندس تہِ چھہ نہ پننہِ جسمک اختیار بلکہ زنانہِ ہند اختیار آسان۔\n5.\\tاَکھ أکِس سٍتـ̡ دھوکہٕ دِیُن، سوائے کینژس کالس خٲطرٕ رضامندی سٍتـ̡ روزٕ تہٕ نمازس مَنٛز دِنہٕ۔ تہٕ دُبارٕ یِکہٕ وٹہٕ، یُس شیطان چُھہ نہٕ تۅہہِ ہٕنزِ بے ضابطگی خٲطرٕ لالچ۔\n6.\\tمگر بہٕ چُھس یہ اجازت سٍتـ̡ بولان، {تہٕ} نہٕ حکمہٕ سٍتـ̡ ۔\n7. تکیازِ بہٕ چُھس یژھان زِ سٲری انسان آسن میہ پانس ہِندۍ پٲٹھۍ۔ مگر پریتھ انسانس چھہ خدایہ سند منٲسب تحفہ میلان، اکہ پتہ تہ تمہ پتہ بییِہ۔\n8.\\tبہٕ چُھس غیر خاندرٕ تہٕ بیواہ ہُند وَنُن زِ تِمن ہٕندِ خٲطرٕ چُھ بہتر۔\n9.\\tمگر اگر تِم نہ تھپھ کٔرِتھ، تِمن گژھن خاندر کرُن، تکیازِ دزنہٕ کھۅتہٕ چُھ خاندر کرُن بہتر۔\n10. تہٕ خانٛدرٕ وٲلِس سٍتـ̡ چُھس بہٕ حُکُم کَران، {توتہِ} بہٕ نہٕ بہٕ بلکہ خداوند، زنانہٕ گژھہِ نہٕ پننِس خانٛدارس نِش الگ گژھُن:\n11.\\tمگر اگر سۅ نیرِ، تیلہِ گژھہِ سۅ غیر خاندر، نتہ گژھہِ خاوند سٍتۍ صلح کرُن: تہٕ خاوند گژھہِ نہ پننہِ زنانہِ ترٲوِتھ۔\n12.\\tمگر باقین سٍتـ̡ چُھہ بہٕ کتھ کران، نہ رب سٍتـ̡ یێلہِ کٲنسہِ بٲے سٕنزِ خانٛدارِنۍ آسہِ تہٕ سُہ أمِس سٍتـ̡ روزُن خۅش آسہِ، سُہ گژھِ نہٕ أمِس سٍتـ̡ دوٗر کٔرِتھ۔\n13.\\tتہٕ سُہ خانٛدار یُس نہٕ ایمان آسہِ، تہٕ اگر سُہ أمِس سٍتـ̡ روزُن خۅش آسہِ، سُہ گژھِ نہٕ أمِس سٍتـ̡ تراوُن۔\n14.\\tکافر خانٛدار چُھ خانٛدارِنہِ ہٕندِ دٔسۍ پاک کرنہٕ آمُت، تہٕ کافر خانٛدارِنہِ ہٕندِ دٔسۍ پاک کرنہٕ آمٕژ، نتہٕ ٲسِہ تُہٕندِ شُرِ ناپاک ۔ مگر وۅنۍ چھا تم مقدس۔\n15. مگر اگر کافر نیرِ، سُہ گژھہِ نیرُن۔ یِتھٮ۪ن معاملن مَنٛز چُھنہٕ بٲے یا بینہِ غلامی منز آسان: مگر خداین چُھ اسہِ امنُک دعوت دِژمُت۔ {امن: Gr. in peace}\n16.\\tژیہ کیا چُھہ پتاہ زِ ژے کٔرِو پنُن خانٛدار؟ یا ژیہ کتھہ پاٹھۍ چھکھ پتاہ زِ ژیہ کٔرِکھ پننہِ زنانہِ بچاو۔ {کتھہ پاٹھۍ: Gr. کیا}\n17. یِتھٕ پٲٹھـ̡ خداین چُھ پرٮ۪تھ أکِس انسانس بٲگرٲومُت، یِتھٕ پٲٹھـ̡ خداوند چُھہ پرٮ۪تھ أکِس بُلاونہٕ آمُت، تِتھے پٲٹھـ̡ گژھہِ سُہ پَکُن۔ تہٕ یِتھٕ پٲٹھۍ چُھس بہٕ سارنٕے گرجا گھرن مَنٛز مقرر کران۔\n18.\\tکٲنسہِ انسانس چھا ختنہ کرنہٕ آمُت وننہٕ یوان؟ سُہ گژھ نہٕ ختنہ کرنہٕ یُن۔ کیا کانہہ چھہ نہ ختنہ کرنہ آمت؟ تس گژھہِ نہ ختنہ کرنہ۔\n19. ختنہ کرُن چُھ نہٕ کانہہ تہِ، تہٕ ختنہ کرُن چُھ نہٕ خدایہ سٕندِس حکمس پیٹھ عمل کرُن۔\n20. پریتھ انسان گژھہِ اتھۍ بلاونس منز روزُن یتھ منز تس بُلاونہٕ آو۔\n21.\\tژیہ چھا نوکر وننہ آمت؟ امچ پرواہ نہ کرُن: مگر اگر ژیہ آزاد گژھہِ، بلکہ کرو {یہ} استعمال۔\n22. یُس خداوند سٕندِس مَنٛز بُلاونہٕ چُھ یِوان، سُہ چُھ خداوند سُند آزاد انسان، یِتھے پٲٹھـ̡ یێلہِ سُہ چُھہ مسیح سُند خادم ۔ {فری مین: Gr. made free}\n23.\\tتم چھہِ قٲمتس سٍتۍ ہینہ یوان۔ تم گژھ نہٕ انسانن ہٕندِ خادم۔\n24. بھائیو، پرتھ کانہہ انسان، یتھ منز تس بُلاونہٕ چُھ، گژھہِ خدایہ سٍتـ̡ روزُن۔\n25. وۅنۍ چُھہ نہٕ کُنوارِین مُتلق میہ خداوند سُند کانہہ حُکُم، توتہِ چُھس بہٕ پنُن فٲصلہٕ دِوان، یُس خداوند سٕنز رحمت حٲصل کٔرِتھ وفادار روزُن۔\n26.\\tبہٕ چُھس باسان زِ یہِ چُھ موجودٕ مصیبت خٲطرٕ اصل، {بہٕ چُھس ونان}، زِ {یہِ} چُھ أکِس انسانس خٲطرٕ اصل۔ {پریشانی: یا، ضرورت}\n27.\\tژیہ چھا زنانہِ سٍتۍ پابند سپدان؟ یلہٕ گژھُن نہٕ ژھارُن۔ ژیہ چھکھ زنانہِ نشہِ آزاد گومت؟ خانٛدارِنۍ ژھانڈنہٕ نہٕ۔\n28.\\tمگر اگر ژیہ خاندر کرِ، تیلہِ چُھہ نہٕ ژیہ گناہ کورمُت۔ تہٕ اگر کنواری خاندر کرِ، تٔمِس چُھ نہٕ گناہ کورمُت۔ توتہِ گژھہِ یِتھۍ مصیبت جسمس منز مگر بہٕ چھُس ژے بچاو۔\n29.\\tمگر بہٕ چُھس یہِ ونان زِ یِمن دۅشوٕے زنانہٕ آسہِ تِمن ہٕندِس پٲٹھۍ، یِمن ہٕندِس سٍتـ̡ آسہِ نہٕ کانہہ تہِ۔\n30. تہٕ یِم روان چھِ، گویا تِم روو نہٕ۔ تہٕ یِم خۅش چھِ، گویا تِم چھِ نہٕ خۅش گَژھان۔ تہٕ تم یم ہیکان چِھ، گویا تمن نِش چُھ نہٕ؛\n31.\\tتہٕ یِم یِم اتھ دنیاہس غلط استعمال کران چھِ، تِکیازِ یِم دُنیاہُک فیشن چھُ ختم سپدان۔\n32. مگر بہٕ کٔرٕ ژےٚ احتیاط ورٲے ۔ یُس غیر خاندرٕ چُھہ تِمن چیزن ہُند خیال تھاوان یُس خداوند سٕندِس سٍتـ̡ چُھہ کِتھہ پٲٹھـ̡ خدایہِ سٕندِس سٍتـ̡ خوش کٔرِتھ: {یُس چُھ...: Gr. of the Lord}\n33.\\tمگر یُس خاندر کٔرِتھ آسہِ سُہ دُنیاہس منز موجود چیزن ہُند خیال تھاوان، سُہ کِتھہ کٔنۍ ہیکہِ پننہِ زنانہِ خوش کٔرِتھ۔\n34.\\tزنانہِ تہٕ کنوارِس درمیان تہِ چھیہ فرق۔ غیر خاندرٕ زنانہٕ چھے خداوند سٕندِس چیزن ہُند خیال تھاوان، یُتھ سُہ جسمس تہٕ روحس منز پاک روزِ، مگر یُس خاندرٕ آسہِ سُہ دنیاہٕکین چیزن ہُند خیال تھاوان، سُہ کِتھہ پٲٹھـ̡ ہیکہِ پننِس خاوندس خوش کٔرِتھ۔\n35.\\tتہٕ یہ چھُس بہٕ پننہِ نفع خٲطرٕ کتھ کران۔ نہ امہ مۅکھہ زِ بہٕ کرٕ ژیہ ژیہ پھنس، بلکہ تمہِ خاطرہ یُس خوبصورت چھُ، تہٕ یُس ژیہ رٔلتھ رٔنگۍ رٔنگۍ رٔٹِتھ رٔٹِتھ رٔٹِتھ۔\n36.\\tمگر اگر کانہہ انسان یہ سوچان زِ سُہ چُھ پننہِ کنوارِ سٍتـ̡ بد سلوک کران، یێلہِ سُہ وٲنسہِ ہٕندِس پوشس نیرِ، تہٕ یێلہِ یێلہِ سُہ یێلہِ تہٕ یێلہِ سُہ کرُن، سُہ کرُن نہٕ گناہ تہٕ تِمن کرُن خاندر کرنہٕ۔\n37. بہر حال یُس پننِس دلس مَنٛز ڈٔٹِتھ روزان چُھ، یُس نہٕ کانہہ ضرورت آسہِ، مگر سُہ چُھ پننہِ مرضی پیٹھ اختیار تھاوان، تہٕ پننِس دِلس مَنٛز یُتھ حکم دِوان چُھ زِ سُہ کرِ پنٕنۍ کنواری رژھراونہٕ، سُہ چُھ اصل کٲم کران۔\n38.\\tیێلہِ یُس خاندرس منز دِوان چُھہ سُہ چُھہ رژھران۔ مگر یُس نہٕ خاندرس منز دِوان چُھ، سُہ چُھ بہتر کران۔\n39.\\tزنانہٕ چھے توٚت تام قانونُک پابند روزان یوتام تٔمۍ سُند خاوند زندٕ آسہِ۔ مگر اگر تٔمۍ سُند خانٛدار مٔرِتھ آسہِ، تٔمِس چھِ آزاد، یٔمِس سٍتۍ خانٛدر کٔرِتھ آسہِ۔ صرف رب سٕندِس مَنٛز چُھ۔\n40.\\tمگر سۅ چھیہ زیادہ خوش روزان، میانہِ فیصلہٕ پتہٕ: تہٕ بہٕ چُھس یہ تہِ سوچان زِ میہ چھہ خدایہ سُند روح موجود۔","1.\\tوۅنۍ چھہ اسہِ سارنے علمن ہنز زان زِ اسہِ سارنے چھہ علم۔ علم چُھ پھۄلُن، مگر خیرات چُھ ترمیم کران۔\n2.\\tتہ اگر کانہہ انسان یہ سوچان زِ سہ چھہ کانہہ چیز زانان تہ تس چھہ نہ وُنیُک کانہہ تہِ پتاہ۔\n3.\\tمگر اگر کانہہ انسان خدایہ سٍتۍ محبت کران چھُ، تیلہِ چھہ تس سٍتـ̡ تہِ پتاہ سپدان۔\n4. تَمہِ مۄکھٕ چُھ تِمن چیزن ہٕندِس کھینس متعلق، یِم بُتن ہٕندِ خٲطرٕ قربانی دِنہٕ یوان چھِ، اسہِ چھِ زانان زِ اکھ بُت چُھ نہٕ دُنیاہس مَنٛز کانہہ تہِ، تہٕ یِہ چُھ نہٕ اَکہِ علاوٕ کانہہ تہِ خدا۔\n5.\\tیێلہِ دیوتا وَننہٕ یِوان چھِ، چاہے آسمانس مَنٛز یا زمینس مَنٛز، (یِتھٕ پٲٹھـ̡ واریاہ دیوتا تہٕ خدایہ واریاہ چھِ،)\n6. مگر اسہِ خٲطرٕ چُھ اَکھ خدا، باپ، یٔمِس سٍتـ̡ سارِنٕے چیز، تہٕ أسـ̡ أمِس مَنٛز۔ تہٕ اَکھ خداوند عیسیٰ مسیح، یٔمۍ سٕندِ ذریعہٕ سٲری چیز چھِ، تہٕ أسۍ تٔمۍ سٕندِ ذریعہٕ۔ {منز: یا، for}\n7. بہرحال چھہ نہ پریتھ انسانس منز یہ علم آسان: تکیازِ کینہہ چھہِ اتھ وقتس تام بُتُک ضمیر تھاوان تہ یہ چھہ بُتس پیش کرنہ آمتس چیز کھیوان۔ تہٕ تِہُند ضمیر کمزور آسنہٕ سٍتۍ چھُ ناپاک سپدان۔\n8.\\tمگر ماز چھہ نہ اسہِ خدایس سٍتـ̡ بہتر سپدان۔ تہٕ اگر أسۍ نہٕ کھیٚوان چھِ، تیٚلہِ چھِ أسۍ بدتر آسان۔ {أسۍ چھا بہتر: یا اسہِ چھا زیادٕ} {اسہِ چھا بدتر: کِنہ، اسہِ چھا کم}\n9. مگر دھیان تھاوُن زِ یہ آزادی بنہِ کُنہِ تہِ طریقہٕ تِمن ہٕندِ خٲطرٕ یِم کمزور چھِ۔ {آزادی: یا، طاقت}\n10.\\tیێلہِ یێلہِ کانہہ تہِ شخص یُس زان آسہِ تۅہہِ بُت سٕندِس مندرس مَنٛز مازس پیٹھ بِہتھ وُچھِ، تێلہِ گژھہِ نہٕ کمزور سُند ضمیر تِم چیز کھٮ۪نہٕ خٲطرٕ حوصلہٕ دِنہٕ یُس بُتَن دِنہٕ یوان چھُ۔ {حوصلہ افزائی: Gr. edified}\n11. تہٕ تێہٕندِس علمہٕ سٍتـ̡ گژھہِ کمزور بوے مارُن، یێمہِ سٕندِ خٲطرٕ مسیح موٗد؟\n12. مگر یێلہِ تُہۍ باین سٍتـ̡ یُتھ گۅناہ کٔرِو، تہٕ تِہُند کمزور ضمیر مجروح کٔرِو، تێلہِ چُھہ مسیحس خلاف گۅناہ کران۔\n13.\\tتێلہِ اگر ماز میٲنس بٲیس ناراض کرِ، بہٕ کھیوٚو نہٕ کانہہ ماز یُس دُنیا کھڑا آسہِ، نتہٕ بہٕ کرٕ پننِس بٲیس ناراض کرنہٕ۔","1. کیا بہٕ چُھس نہٕ رسول؟ بہٕ چھُس نہٕ آزاد؟ کیا مے چُھہ نہٕ عیسیٰ مسیح سُند رب وُچھمُت؟ کیا تُہۍ چھِو نہٕ خداوند سٕندِس مَنٛز میٲنۍ کٲم؟\n2. یێلہِ بہٕ چُھس نہٕ باقیَن ہٕندِ خٲطرٕ رسول، توتہِ چُھس بہٕ تہٕ بێشک تہٕ چُھس بہٕ تہٕ تێلہِ چُھہ تێہہِ سٍتـ̡ تہٕ یێلہِ چُھہ تُہٕندِس رسولس سٍتـ̡ تہٕ یێلہِ تہٕ چُھہ تێلہِ سٍتـ̡ تہٕ یێلہِ چ\n3.\\tیِمن ہُند جواب چھُ یِم میہ پرکھان چھِ،\n4. کیا اسہِ چھا نہٕ کھٮ۪نُک تہٕ چیٚنہٕ خٲطرٕ طاقت؟\n5. کیا اسہِ چُھنہٕ أکِس بینہِ، خانٛدارِن، تہٕ باقٕے رسولن تہٕ خداوند سٕندِس بٲے تہٕ سیفاسس سٍتـ̡ رہبری کرنُک اِختِیار تھاوان؟ {خاتون: یا، زنانہٕ}\n6. یا صرف میہ تہٕ برنباس، کیا اسہِ چھا نہ کٲم کرنہٕ نِش پرہیز کرنُک اختیار تھاوان؟\n7. کُس چُھ پننِس اِلزامس پیٹھ کُنہِ ساتہٕ جنگ کران؟ کُس چُھ انگور باغ لاگان تہٕ اَمہ کِس پھلہٕ سٍتـ̡ چُھہ نہٕ کھٮ۪وان؟ یا یُس ریوُس کھیٚوان چُھ، تہٕ یُس نہٕ ریوُک دۄد کھٮ۪وان چُھ؟\n8.\\tمیہ چھہ یہ کتھ بحیثیت انسان ونان؟ یا شریعت تہِ چھہ نہ یۅہے ونان؟\n9.\\tیِہ چُھہ موسیٰ سٕندِس شریعتس مَنٛز لیکھنہٕ آمُت زِ ژے گژھ نہٕ داند سٕندِس ٲسس مٔنزۍ کٔرِتھ یُس مَکٲے کٔرِتھ چھُ۔ کیا خدا چھُ بیلن ہُند خیال تھاوان؟\n10.\\tیا چھہ سہ ونان زِ سٲنس خاطرہ چھہ پورہ پاٹھۍ ونان؟ سانہِ خاطرہ چھہ نہ کانہہ شک زِ {یہ} چھہ لیکھنہ آمت: یُس ہل چُھس وۅمید کٔرِتھ ہل چلاوُن۔ تہٕ یہ زِ یُس وۅمید منز تھپھ کٔرِتھ آسہِ سُہ گژھہِ پننہِ وۅمید منز شریک آسُن۔\n11.\\tاگر اسہِ چُھہ تۅہہِ خٲطرٕ روحٲنی چیز ووتمُت، کیا یہ چھا بۆڈ کتھ اگر أسۍ چانہِ جسمٲنی چیزن ہُند لُٹنہٕ یِو؟\n12.\\tاگر باقٕے تۅہہِ پیٹھ {یہ} اقتدارس منز شریک چھِ، {کیا چھُ} أسۍ نہٕ بٔلکہِ؟ بہر حال، اسہِ چُھ نہٕ یہٕ طاقت استعمال کٔرمٕژ۔ مگر سارِنٕے چیزن ہٕندِس مصیبت سٍتـ̡ گژھہِ اسہِ مسیح سٕنزِ انجیل منز رُکاوٹ۔\n13. کیا تۅہہ چُھہ نہٕ پتاہ زِ یِم مقدس چیزن ہٕنز خدمت کران چِھہ تم چِھ ہیکل کین چیزن منز زندٕ روزان؟ تہٕ یِم قربان گاہس پیٹھ انتظار کران چھِ، تم چھا قربان گاہس سٍتـ̡ شریک سپدان؟ {لائیو: یا، فیڈ}\n14. یێتھے پٲٹھـ̡ چُھ خداوند مقرر کورمُت زِ یِم انجیل ہٕنز تبلیغ کران چِھہ تِم گژھن انجیل سٍتـ̡ زندٕ روزٕنـ̡ ۔\n15.\\tمگر میہ چھہ نہ یمن منز کانہہ تہِ چیز استعمال کورمُت: نہ چھہ میہ یِم چیز لیوکھمُت، زِ یہ گژھہِ میانہِ خاطرہ یۅہے کرنہٕ یُن، تکیازِ میانہِ خاطرہ گژھہِ بہتر زِ کانہہ تہِ انسان گژھہِ میون جلال ختم کرُن۔\n16. یێلہِ بہٕ انجیل ہٕنز تبلیغ کران چُھس، تێلہِ چُھہ نہٕ میہ کانہہ تہِ جلال دِنہٕ خٲطرٕ: تێکیازِ میہ چُھہ ضرورت۔ آ، افسوس، اگر بہٕ انجیل ہنز تبلیغ کرٕ نہٕ!\n17. یێلہِ بہٕ یێلہِ یہِ کٲم پننہِ مرضی سٍتـ̡ کٔرِتھ، تێلہِ چُھہ میہ اکھ انعام: مگر یێلہِ میانہِ مرضی خلاف چُھہ انجیل ہُند اِنتِظام کرنہٕ آمُت۔\n18. تیلہٕ کیا چُھ میون انعام؟ {پٔزۍ} یێلہِ بہٕ انجیل ہٕنز تبلیغ کٔرِتھ، بہٕ ہێکہٕ عیسیٰ سٕنز انجیل بغٲر الزام دِتھ، یێلہِ بہٕ ہێکہٕ نہٕ انجیل مَنٛز پنُن طاقتُک غلط استعمال کٔرِتھ۔\n19. یێلہِ بہٕ سارِنٕے نِش آزاد آسہِ، توتہِ چھُس بہٕ سارِنٕے ہُند خادم بنوومُت، یُتھ بہٕ زیادٕ حٲصِل کٔرِتھ۔\n20. تہٕ یہودین خٲطرٕ بنیوو بہٕ یہودی بٔنِتھ، یُتھ بہٕ یہودی حٲصل کٔرِتھ۔ تِمن خٲطرٕ یِم قانونس تحت چھِ، یِتھ کٔنۍ قانونس تحت چھِ، تاکہ بہٕ ہیٛکہٕ تِم حٲصل کٔرِتھ یِم قانونس تحت چھِ۔\n21.\\tتِمن ہٕندِ خٲطرٕ یِم شریعت ورٲے چھِ، یِتھ کٔنۍ شریعت ورٲے چھِ، (خدایہِ سٕندِ خٲطرٕ شریعت ورٲے نہٕ آسنہٕ کِنۍ، بلکہ مسیح سٕندِس شریعت سٍتـ̡ چھِ،) یُتھ بہٕ ہێکہٕ تِم حٲصل کٔرِتھ یِم شریعت بغٲر چھِ۔\n22.\\tکمزورن ہٕندِ خٲطرٕ بنیوو بہٕ کمزور، یُتھ بہٕ ہێکہٕ کمزور حٲصل کٔرِتھ: بہٕ چُھس سارنٕے انسانن ہٕندِ خٲطرٕ سارِنٕے چیز بناونہٕ آمُت، یُتھ بہٕ ہێکہٕ بہٕ بہٕ کُنہِ سٍتـ̡ بچٲوِتھ۔\n23. تہٕ بہٕ چُھس یہِ انجیل ہٕندِ خٲطرٕ کران، یُتھ بہٕ ہێکہٕ اتھ سٍتـ̡ شریک سپدِتھ {ژے}۔\n24.\\tژیہ چھے نہ پتاہ زِ یِم ریسہِ منز دوڑان چھِ، تم چھہِ سارِنٕے سٍتۍ رلان مگر أکِس چھُ انعام میلان۔ لہذا ژٔلِو، تاکہ تُہۍ حٲصِل کٔرِتھ۔\n25. تہٕ پریتھ کانہہ انسان یُس مہارت حٲصل کرنٕچ کوشش کران چُھ، سُہ چُھ پرٮ۪تھ چیزس مَنٛز معتدل آسان۔ وۅنۍ چھہِ تم اکھ بدعنوان تاج حٲصل کرنہ خاطرہ {یہ کران}۔ مگر أسۍ چھہِ اکھ غیر بدعنوان۔\n26.\\tبہٕ چُھس تَمہِ کِنۍ ژلان، تیوٗت غیر یقینی طور نہٕ۔ لہذا لڑو بہ، نہ تِتھۍ پٲٹھۍ یُس ہوہس ماران چھُ:\n27.\\tمگر بہٕ چھُس پننِس جسمس تل تھاوان، تہٕ یہِ کُنہِ تہِ طٔریٖقہٕ سٍتـ̡ یێلہِ بہٕ باقین تبلیغ کٔرِتھ، بہٕ گژھہٕ پانہٕ کُنہِ تہِ رٔٹِتھ ۔","1. امہِ علاوٕ، بٲے، بہٕ چُھس نہٕ یژھان زِ تۅہہ گژھ جٲہِل آسُن، زِ سانۍ سٲری باپ ٲسۍ اوٚبرس تَل، تہٕ سٲری ٲسۍ سمندرٕ کِنۍ گٔمٕتۍ۔\n2. تہٕ سارِوٕے آیہ موسیٰ سٕندِ خٲطرٕ اوبرس تہٕ سمندرس مَنٛز بپتسمہ دِنہٕ۔\n3. تہٕ سارِوٕے کھیوٚو اکوے روحٲنی ماز۔\n4.\\tتہٕ سارِوٕے کٔر اکوے روٝحٲنی شراب: تِکیازِ تِمو چُھ تِمن پَتہٕ یِنہٕ وٲلِس روٝحٲنی کٔنہِ سٍتـ̡ چُھہ: تہٕ سُہ چُھ مسیح۔ {فالو کٔر...: یا، گٔیہِ تمن سٍتۍ}\n5. مگر یِمو منزٕ واریاہن سٍتـ̡ اوس نہٕ خدا خۅش گومُت، تِکیازِ تِم گٔیہِ بیابانن مَنٛز الٹنہٕ۔\n6.\\tوۅنۍ ٲس یِم چیز سانہِ مثالہٕ، یُس ارادہ زِ اسہِ پزِ نہٕ بد چیزن ہٕنز ہوس کٔرٕن، تِکیازِ تِمو تہِ ٲس ہوس کران۔ {سانۍ...: Gr. سانہِ اعداد و شمار}\n7.\\tنہ گژھ تم مشرک تہ یتھے پاٹھۍ کینہہ ٲسۍ۔ یتھہ پاٹھۍ لیکھنہ آمت چھہ زِ لوکھ بیوٹھ کھیوٚن چیوان تہ ووٚتھ گِندنہِ۔\n8.\\tاسہِ پزِ زنا کٔرِتھ، یِتھہٕ کٔنۍ یِمو منزٕ کینہہ کٔرۍ، تہٕ أکِس دۅہس منز گٔیہِ تریہ وُہن ساس۔\n9. نہ کرو اسہِ مسیحس آزماونہٕ، یِتھ کٔنۍ یِمو منزٕ کینہہ تہِ آزمائش کٔرۍ، تہٕ گٔیہِ ناگن سٍتـ̡ تباہ کرنہٕ۔\n10.\\tنہ تہِ کٔرِو تِمو منزٕ کینہہ بڑبڑاوُن، تہٕ گٔیہ تباہ کرن وٲلِس تباہ کٔرِتھ۔\n11.\\tوۅنۍ سپد یِم سٲری چیز یِمن سٍتـ̡ نمونن ہٕندِ خٲطرٕ لیکھنہٕ آمٕتۍ، تہٕ یِم چھِ سانہِ نصیحتہٕ خٲطرٕ لیکھنہٕ آمٕتۍ، یٔمِس پیٹھ دُنیاہُک اند چھُ آمُت۔ {ensamples: or, types}\n12. یُس سُہ کھڑا چُھس سُہ سوچان چُھ، سُہ گژھہِ ہوشیار روزُن۔\n13.\\tکانہہ فتنہ چُھہ نہٕ تۅہہِ سٍتـ̡ یُس انسانس سٍتـ̡ عام چُھ، مگر خدا چُھہ وفادار، یُس نہٕ تۅہہِ ہٕندِس قٲبلس سٍتـ̡ آزماونہٕ یِوان۔ مگر فتنہ سٍتۍ تہِ گژھہِ ژلنچ وتھ تہِ، یُتھ ژیہ برداشت کرُن۔ {عام...: یا، اعتدال پسند}\n14. اَمہِ مۄکھٕ ژٔلِو میٲنۍ پیاری بت پرستی نِش۔\n15. بہٕ چُھس دانشمندن ہٕنز کتھ کران۔ بہٕ کیا چُھس ونان تہٕ فیصلہ کٔرِو۔\n16. سُہ پیالہ یُس أسۍ برکت دِوان چُھ، کیا یہِ چُھہ نہٕ مسیح سٕندِ خونُک تعاون؟ یُس روٹی أسـ̡ پھُٹراوان چُھ، کیا سُہ چُھہ نہٕ مسیح سٕندِس جسمس سٍتـ̡ رٔٹِتھ؟\n17.\\tاسہِ کیازِ واریاہ چھہِ اکھ روٹی، {تہٕ} اکھ جسم: تکیازِ أسۍ سٲری چھہِ تمہِ اکہِ روٹی منز شریک سپدان۔\n18.\\tوُچھِو اسرٲیلِس مازس پَتہٕ: یِم قربانی کھٮ۪وان چھِ، تِم چھِنہٕ قربان گاہَس مَنٛز شریک سپدان؟\n19. تیلہِ کیا چُھس بہٕ ونان؟ یہ زِ بت چھہ کانہہ چیز، یا یُس بتن قربان کرنہ یوان چھہ سہ چھا کانہہ چیز؟\n20. مگر بہٕ چُھس ونان زِ یِم چیز غیر قومن قربان کران چھِ، تِم چھِ شیطانن خٲطرٕ قربان کران، نہ کہ خدایس سٍتـ̡ تہٕ بہٕ چُھس نہٕ یژھان زِ ژے گژھہِ شیطانن سٍتـ̡ رفاقت کٔرِتھ۔\n21. تہٕ یێلہِ ہیٛکو نہٕ خداوند سُند پیالہ تہٕ شیطان سُند پیالہ چِھتھ ہیکو نہٕ۔\n22. کیا أسۍ چھِ رب حسد کرنہٕ خٲطرٕ اکساوان؟ کیا أسۍ چھا أمِس کھوتہٕ زیادٕ مضبوط؟\n23.\\tسٲری چیز چھہ میانہِ خاطرہ حلال مگر سٲری چیز چھہِ نہ مصلحت: سٲری چیز چھہِ میانہِ خاطرہ جائز، مگر سٲری چیز چھہِ نہ میانہِ خاطرہ حلال مگر سٲری چیز چھہِ نہ مصلحت بخشان۔ {مصلحت: یا، نفع بخش}\n24. کانہہ تہِ انسان گژھہِ نہ پنن پان ژھارُن، بلکہ گژھہِ پریتھ انسان بییِس سُند دولت۔\n25.\\tیُس تہِ کٕننہٕ یِوان چھُ، سُہ کھٮ۪وان چھُ، ضمیرٕ خٲطرٕ چھُنہٕ کانہہ سوال پرژھان:\n26. زٔمیٖن چُھہ خداوند سُند تہٕ اَمہ سٍتـ̡ پورٕ سٍتـ̡ ۔\n27. یێلہِ یێلہِ یِمو منزٕ کانہہ تہِ یُس ایمان تھاوان آسہِ نہٕ تہٕ تۅہہِ گژھنُک حکم دِیہِ۔ یُس تہِ ژیہ برونہہ کنہِ تھاونہ آمت چھہ، کھیوٚن نہ ضمیرس خاطرہ کانہہ سوال۔\n28. مگر یێلہِ کانہہ انسان چُھہ تۅہہِ ونان، یہِ چُھہ بُتن ہٕندِ خٲطرٕ قربان کرنہٕ آمُت، تٔمِس سٕندِ خٲطرٕ مہٕ کھیوٚن یُس یہِ ہٲومُت چُھ، تہٕ ضمیرٕ خٲطرٕ: یێلہِ زٔمیٖن چُھہ خداوند سُند تہٕ اَمہ سٍتـ̡ پورٕ پٲٹھۍ۔\n29.\\tضمیر، بہٕ چُھس ونان، نہ تُہند پنُن بلکہ بییِس سٍتـ̡ کیازِ میانہِ آزٲدی ہُند فیصلہ چُھ بییِس {انسانس} سٕندِس ضمیرس سٍتـ̡ کرنہٕ یوان؟\n30. یێلہِ بہٕ فضل سٍتـ̡ شریک آسہِ، تێلہِ کیازِ چُھس بہٕ بد کتھ کران ییمہِ خٲطرٕ بہٕ شُکر ادا کران چُھس؟ {گریس: یا، تھینکس گیونگ}\n31. تێمہِ کِنۍ یێلہِ تہِ کھٮ۪وان یا چیٚو، یا یُس تہِ تہِ کرِو، سٲری کٔرِو خدایہ سٕندِ جلال خٲطرٕ۔\n32. یہودین تہٕ نہ غیر قومن تہٕ نہ خدا سٕندِس کلیساہس سٍتـ̡ کُنہِ تہِ جُرمُک دِیُن: {غیر قومی: Gr. Greeks}\n33.\\tیێلہِ بہٕ سارِنٕے {انسان} سارِنٕے {چیز} سٍتـ̡ خۅش کران چُھس، پنُن نفع ژھاران نہٕ بلکہ واریاہن ہُند {نفع}، یُتھ زن تِم بچاونہٕ یِن۔","1. یێلہِ بہٕ تہِ چُھس مسیح سُند پیروکار تہِ۔\n2. وۅنۍ چُھس بہٕ تۅہہِ تعریف کران زِ تۅہہ چھِو میہ پرٮ۪تھ چیزس مَنٛز یاد تھاوُن، تہٕ یِتھٕ کٔنۍ میہ تۅہہِ تام واتنوومُت چھُ۔ {آرڈیننس: یا، روایتہٕ}\n3. مگر بہٕ چُھس ژیہ زانُن زِ پریتھ انسان سُند سر چُھ مسیح۔ تہٕ زنانہِ ہُند کلہٕ {چُھ} مرد۔ تہٕ مسیح سُند کلہٕ چُھ خدا۔\n4.\\tپریتھ انسان یُس دعا کران یا پیشن گویی کران اوس، کلہ تھوٚپ کٔرِتھ چھہ پننس کلس بے عزتی کران۔\n5.\\tمگر پریتھ زنانہِ یُس کلہ ورٲے دعا کران یا پیشن گویی کران آسہِ، سہ چھہ کلہ بے عزتی کران: تکیازِ سۅ چھیہ سۅ تہِ یۅہے زن کھورِ کڈنہ آمژ۔\n6.\\tیێلہِ زنانہِ ہٕندِس پوشہٕ سٍتـ̡ تہِ گژھہِ ژٹنہٕ یُن، مگر اگر زنانہِ ہٕندِ خٲطرٕ ژُٹنہٕ یا کھوٗر کرُن شرم آسہِ، تیلہِ گژھہِ سُہ پوشہٕ کرُن۔\n7. یێلہِ پٲٹھـ̡ پَزِ پَزِ نہٕ پَنٕنـ̡ کَلہٕ تھوٚپُن، تِکیازِ سُہ چُھہ خدایہِ سٕنز شبیہہ تہٕ جلال آسان، مگر زنانہٕ چھے مردٕ سٕنز شان۔\n8. تکیازِ مرد چُھ نہٕ زنانہِ ہُند آسان۔ مگر مردٕ سٕنز زنانہٕ۔\n9.\\tمرد اوس زنانہِ ہندِ خاطرہ تخلیق کرنہ آمت۔ مگر مردس خٲطرٕ زنانہٕ۔\n10.\\tامہ مۅکھہ گژھہِ زنانہِ فرشتن ہندِ خاطرہ پننس کلس پیٹھ طاقت آسُن۔ {پاور: یہِ چھُ اکھ پردٕ زِ سۄ چھِ پننِس خانٛدار سٕنٛدِس طاقتس تحت}\n11. توتہِ چُھ نہ مرد زنانہٕ ورٲے تہٕ نہ زنانہٕ چُھہ مردٕ سٕندِس سٍتـ̡ خداوندٕ سٕندِس سٍتـ̡ ۔\n12.\\tیتھہ پاٹھۍ زنانہ مردس سیتۍ تہِ چھہِ، تتھے پاٹھۍ چھہ مرد تہِ زنانہِ ہندِ طرفہ تہِ۔ مگر خدایہ سٕندِ سارِنٕے چیز۔\n13.\\tپننِس پانس مَنٛز کٔرِو فٲصلہٕ: کیا یہ چُھہ خۅش زِ زنانہٕ چھے خدایہ سٕندِس سٍتـ̡ دُعا کٔرِتھ؟\n14.\\tقدرت تہِ چھہ نہ یہ ہیچھناوان زِ اگر کٲنسہِ انسانس زیوٹھ مس آسہِ، سہ چھہ تس شرمندگی؟\n15.\\tمگر اگر زنانہِ زیوٹھ مس آسہِ، سُہ چھُ تٔمِس خٲطرٕ عظمت: تکیازِ أمِس چھُ مَس پوشہٕ خٲطرٕ دِنہٕ یِوان۔ {کور کٔرتھ: یا، پردہ}\n16. مگر اگر کانہہ انسان متنازعہ باسان چُھ، اسہِ چُھہ نہٕ یُتھ کانہہ رواج، تہٕ نہ چُھہ خدایہ سٕندِ کلیساہٕ۔\n17. وۅنۍ یُس بہٕ ژے اعلان کران چُھس، بہٕ چُھس نہٕ تۅہہ تعریف کران زِ تۅہہ گژھہِ نہ بہتری خٲطرٕ بلکہ بدتر خٲطرٕ یکجا سپدان۔\n18. سارِوٕے کھۄتہٕ گۅڈٕ ییلہ تہۍ کلیساہس مَنٛز یکوٹہ گژھان چھِو، بہٕ چُھس بوزان زِ تۅہہِ درمیان چُھہ تقسیم سپدان۔ تہٕ بہٕ چُھس کُنہِ حدس تام اتھ پیٹھ یقین کران۔ {تقسیم: یا، فرقہ}\n19.\\tیِمن مَنٛز گژھہِ بدعتی تہِ آسٕنۍ، یُس منظوٗر آسہِ تۅہہِ مَنٛز ظٲہر سپدُن۔ {بدعت: یا، فرقہٕ}\n20. یێلہِ یێلہِ أکِس جایہِ یِوان چھِو، {یہِ} چُھہ نہٕ خداوند سُند رٲژ کھٮ۪وان۔ {یہ...: یا، تُہۍ ہیکو نہٕ کھٮ۪تھ}\n21.\\tتکیازِ کھٮ۪نس منز چُھ پرٮ۪تھ کانہہ پنُن شامُک کھٮ۪وان تہٕ أکِس چُھ فاقہٕ تہٕ بیٛاکھ چُھ شراب۔\n22. کیا؟ کیا ژیہ چھکھ نہٕ کھٮ۪نہٕ خٲطرٕ تہٕ چیٚنہٕ خٲطرٕ مکانہٕ؟ یا چُھہ خدا سٕندِس کلیساہٕ سٍتـ̡ حقارت کٔرِتھ، تہٕ تِمن ہٕندِس سٍتـ̡ شرمندٕ کٔرِو؟ بہٕ کیا وَنُن ژےٚ؟ بہٕ کٔرٕ اتھ منز ژےٚ تعریف؟ بہٕ چھُس {تۅہہ} تعریف۔ {چھُنہٕ نہٕ: یا، چھُ غریب؟}\n23. کیازِ میہ چُھہ خداوند سٕندِ طرفہٕ سُہ حٲصل سپدمُت یُس میہ تہِ ژے دِژمُت چُھ، یُس خداوند عیسیٰ سٕندِ دۅکھہٕ سٍتـ̡ دِنہٕ آمُت چُھ، یێمہِ رٲژ سٍتـ̡ تٔمِس دِنہٕ آمُت چُھہ روٝحہِ ہُند رو�\n24.\\tتہٕ ییلہ تٔمۍ شُکر ادا کٔر، تٔمۍ کٔر بریک تہٕ وونُن، نِش کھیوٚن، یہ چھُ میون جسم، یُس ژے خٲطرٕ پھُٹمُت چُھ، یہِ چھُ میانہِ یاد پٲٹھۍ۔ {منز...: یا، یاداشت خاطرہ}\n25.\\tیِتھے پٲٹھـ̡ تہِ تُل پیالہ ییلہ تٔمۍ کھیوٚو، وونُن زِ یہِ پیالہ چُھہ میانہِ خونس مَنٛز نۆو عہد نامہٕ: یێلہِ تہٕ ژے چُھکھ میانہِ یاد پٲٹھۍ۔\n26.\\tیێلہِ یۆت لٹہِ یێلہِ یۆت تہِ یێلہِ یہ روٹی کھیوان تہٕ یہ پیالہ چیوان چُھ، تێلہِ چُھہ رب سُند مرُن ہاونہٕ یُس نہٕ سُہ یِنہٕ سٍتـ̡ ۔ {تم کرو ...: یا، شو یو}\n27. یێمہِ مۄکھٕ یُس یُس یہِ روٹی کھٮ۪یہِ تہٕ خداوند سُند پیالہ چُھہ، سُہ چُھہ خداوند سٕندِس جسمس تہٕ خونُک قصوروار سُہ چُھ۔\n28.\\tمگر انسان گژھہِ پانس پرکھاونہ یُن، تہ یتھہ پاٹھۍ گژھہِ سہ روٹی کھیوٚن تہ پیالہ پییہِ۔\n29.\\tیُس یُس نالائق کھٮ۪وان چُھہ تہٕ چیوان چُھ، سُہ چُھ نہ خداوند سٕندِس جسمس سٍتـ̡ سٍتـ̡ کھیوان تہٕ چیوان چُھ۔ {damnation: یا، فیصلہٕ}\n30.\\tامہ مۅکھہ چھہِ واریاہ کمزور تہ بیمار تہ واریاہ چھہِ شۅنگان۔\n31. تکیازِ اگر أسۍ پانس فیصلہ کرو تیلہِ گژھہِ نہ اسہِ فیصلہ کرنہ۔\n32. مگر ییلہ اسہِ فیصلہ سپدِ، اسہِ چھہ خداوند سٕندِ طرفہٕ سزا دِنہٕ یِوان، یُس نہٕ اسہِ دنیاہس سٍتـ̡ مذمت کرنہٕ یُن۔\n33.\\tتێلہِ ییلہ تم یکوٹہ کھٮ۪نہٕ خٲطرٕ یِوان چھِو، تێلہِ کرو اکھ أکِس خٲطرٕ۔\n34.\\tتہٕ اگر کٲنسہِ فاقہٕ آسہِ، سُہ گژھہِ گَرِ کھٮ۪نہٕ۔ یُس نہٕ تُہۍ یِکہٕ وَٹہٕ یِوان مذمت کرنہٕ۔ تہٕ باقٕے بہٕ یِنہٕ وِزِ ترتیب دِنہٕ۔ {مذمت: یا، فیصلہٕ}","1.\\tوۅنۍ روٝحٲنی {تحفہٕ} متعلق، بہٕ چُھس نہٕ ژے جٲہل۔\n2. تۅہہ چھے پتاہ زِ تم ٲسِو غیر یہودی یِمن کُنہِ بُتن کُن نِنہٕ آمٕتۍ، یێلہِ تہِ یێلہِ تہِ یێلہِ تہٕ یێلہِ تہِ گٔیہِ تُہۍ یِمن کُنہِ بُتن ہٕندِس کُن نِنہٕ آمٕتۍ۔\n3. اَمہِ مۄکھٕ چُھس بہٕ ژےٚ سمجھُن دِوان زِ خدایہِ سٕندِ روحہٕ سٍتـ̡ کتھ کرن وول کانٛہہ تہِ شخص چُھہ عیسیٰ مسیحس ملعون ونان: تہٕ {یہِ} ہیکہِ نہٕ کانہہ تہِ انسان یہ ؤنِتھ زِ عیسیٰ چُھ خداوند بلکہ روح القدس سٍتـ̡ ۔ {لعنت: یا، اناتھیما}\n4. وۅنۍ چھہ تحفن ہند تنوع مگر اکوے روح۔\n5. تہٕ انتظامیہن ہٕندِس اختلافس سٍتـ̡ چُھ، مگر اکوے مالہٕ۔ {انتظامیہ: یا، وزارت}\n6. تہٕ عملن ہٕنز تنوع چِھ، مگر یہ چُھ سُے خدا یُس سارِنٕے سارِنٕے سٍتـ̡ کٲم کران چُھ۔\n7. مگر روح سُند ظہور چُھ پرتھ انسانس دِنہٕ آمُت یُس نفع حٲصل کرنہٕ خٲطرٕ چُھ۔\n8. یێلہِ چُھہ أکِس روٝحہِ سٍتـ̡ حکمت ہُند کلام دِنہٕ آمُت۔ بییِس خٲطرٕ چُھ علمُک کلام امی روح سٕندِ ذریعہٕ؛\n9. امی روحہٕ سٍتـ̡ بییِس عقیدس سٍتـ̡ بییِس خٲطرٕ چھُ امی روٝحہٕ سٍتـ̡ شفا دِنٕکۍ تحفہٕ؛\n10.\\tبییِس کُن معجزاتن ہٕنز کٲم؛ بییِس پیشن گویی کُن؛ روحن ہٕندِس بییِس سمجھس تام؛ بییِس {divers} قسمٕچ زبانہٕ خٲطرٕ؛ بییِس تام زبانن ہنز تشریح:\n11. مگر یِم سٲری چھِ اَکھ تہٕ اَکہِ روح کٲم کران، یُس پرٮ۪تھ أکِس انسانس مَنٛز الگ الگ تقسیم کران چھُ۔\n12. یِتھٕ پٲٹھـ̡ چُھ جسم اَکھ تہٕ أمِس چُھ واریاہ رُکُن، تہٕ اَمہِ أکِس جسمٕکۍ سٲری رُکُن چھِ اَکہِ جسمہٕ سٍتـ̡ اَکھ جسمہٕ: تِتھے پٲٹھـ̡ چُھ مسیح تہِ۔\n13. کیازِکہ اَکہِ روحہٕ سٍتـ̡ چُھہ أسـ̡ سارِوٕے أکِس جسمس مَنٛز بپتسمہ دِنہٕ آمُت، چاہے أسـ̡ یہودی ٲسِو یا غیر یہودی، چاہے أسـ̡ بٔنِتھ یا آزاد ٲسِو۔ تہٕ سٲری چھِ أکِس روحس منز چِنہٕ خٲطرٕ بناونہٕ آمٕتۍ۔ {غیر قومی: Gr. Greeks}\n14. تکیازِ جسم چُھ نہٕ اَکھ رُکُن بلکہ واریاہ آسان۔\n15.\\tاگر کھورِ ونان، کیازِ بہٕ چُھس نہٕ اتھہٕ، بہٕ چُھس نہٕ جسمُک ۔ تیلہٕ چُھ نہٕ یہٕ جسمُک ؟\n16. تہٕ اگر کَن وَنُن، کیازِ بہٕ چُھس نہٕ أچھ، بہٕ چُھس نہٕ جسمُک ۔ تیلہٕ چُھ نہٕ یہٕ جسمُک ؟\n17.\\tاگر سورے جسمس اچھ ٲس، کتہِ ٲس بوزن؟ اگر سورے {ٲس} بوزان آسہِ، کتہِ ٲس خوشبو؟\n18.\\tمگر وۅنۍ چُھ خداین یِمن منز پرٮ۪تھ کانہہ عضو جسمس مَنٛز مقرر کوٚرمُت، یُس أمِس خۅش چُھ کوٚرمُت۔\n19.\\tتہِ اگر یم سٲری اکھ رکن ٲسۍ، لاش کتہِ ٲس؟\n20.\\tمگر وۅنۍ چھہِ واریاہ ارکان، مگر اکھ جسم۔\n21.\\tتہٕ اچھ ہیکہِ نہ اتھس ؤنِتھ، میہ چھیہ نہ چانہِ ہنز کانہہ ضرورت: نہ بییہ کلہ کھورِ تام، میہ چھیہ نہ چانہِ ہنز کانہہ ضرورت۔\n22.\\tبلکہ چھہ جسمکۍ تم اعضاء، یم زیادہ کمزور باسان چھہِ، چھہِ ضروری:\n23.\\tتہٕ تِم {رُکن}، یِمن أسۍ کم عزت مانان چھِ، تِمن پیٹھ چھِ أسۍ زیادٕ عزت دِوان۔ تہٕ سانہِ ناپسندیدٕ {حصہٕ} چھِ زیادٕ زیادٕ خوبصورتی۔ {عطا کٔرِتھ: یا، لاگُن}\n24.\\tسانین خوبصورت حصن ہنز چھیہ نہ کانہہ ضرورت: مگر خداین چھہ جسمس رٔلتھ رٔلتھ دِژمُت، یُس اتھ {حصس} سٍتـ̡ زیادٕ عزت دِژمُت چھُ:\n25.\\tیہ زِ جسمس منز گژھہِ نہ کانہہ اختلاف آسُن۔ مگر {یہ} ارکانن گژھہِ اکھ أکِس ہُند خیال تھاوُن۔ {تفرقہ: یا، تقسیم}\n26. تہٕ اگر أکِس رُکنس تکلیف، سارِنٕے رُکنن چھِ اَتھ سٍتـ̡ تکلیف۔ یا أکِس رُکنَس یِیہِ یزتھ دِنہٕ، سٲری ارکان چھِ اَتھ سٍتۍ خوشی مناوان۔\n27. وُنہِ چُھہ تُہۍ مسیح سُند جسم، تہٕ خاص طور رُکن۔\n28. تہٕ خداین چُھ کلیساہس مَنٛز کینہہ مقرر کٔرۍمٕتۍ، گۅڈٕ رسول، دویِم پیغمبر، تریم اُستاد، اَمہ پَتہٕ معجزات، پَتہٕ شفا دِنٕچ تحفہٕ، مدد، حکومتہٕ، زبانن ہٕنز تنوع۔ {تنوع: یا، قسم}\n29. {کیا } سٲری رسول؟ {کیا } سٲری پیغمبر؟ {کیا } سٲری استاد چھہِ؟ {کیا } سٲری معجزات کرن وٲلۍ؟ {کارکن...: یا، اختیارات؟}\n30.\\tشفا دِنٕکۍ سٲری تحفہٕ؟ سٲری چھا زبانہِ سیتۍ کتھ کران؟ سٲری چھا تشریح کران؟\n31.\\tمگر بہٕ ہٲوِو بہٕ تہٕ بہٕ ہٲوِس بہٕ تہٕ بہٕ ہٲوِتھ","1.\\tیودوے بہٕ انسانس تہٕ فرشتن ہٕنزِ زبانہِ سٍتۍ کتھ کران چھُس، تہٕ بہٕ چھُس نہٕ سٍتـ̡ بٔنِتھ پیتل ہٕندِس پٲٹھۍ، یا ٹِنگہٕ وُن بٔنِتھ۔\n2. تہٕ یودوَے میہ نِش پیشن گویی ہُند تحفہٕ چُھ، تہٕ سارِنٕے اسرار تہٕ سارِنٕے عٔلِم سمجِتھ چھُ۔ تہٕ یودوَے میہ چھُس سٲرۍسٕے ایمان، یُتھ بہٕ ہیوٚک پہاڑ ہٹٲوِتھ، تہٕ بہٕ چھُس نہٕ خیرات کٔرِتھ، بہٕ چھُس نہٕ کیٚنٛہہ۔\n3. تہٕ یودوَے بہٕ پنُن سورے مال غریبن کھٮ۪نہٕ خٲطرٕ دِوان چھُس، تہٕ بہٕ چھُس پنُن جسم زالنہٕ خٲطرٕ دِوان، تہٕ بہٕ چھُس نہٕ خیرات دِوان، اَمہ سٍتـ̡ چُھس نہٕ مےٚ کانہہ فٲیدٕ دِوان۔\n4.\\tخیرات چھہ واریاہس کالس تکلیف، {تہٕ} مہربان۔ خیرات چُھ نہٕ حسد کران؛ خیرات چُھ نہٕ پانہٕ وُچھان، چُھ نہٕ پھۄلاونہٕ آمُت، {vaunteth...: یا، چُھ نہٕ جلدٕ}\n5.\\tسُہ چُھہ نہ پانس بد اخلاق سٍتـ̡ بێیہِ سٍتـ̡ بێیہِ سٍتـ̡\n6. بدکاری منز گژھہِ نہ شاد سپدُن، بلکہ گژھہِ حقیقتس منز شاد سپدُن۔ {حقیقتس منز: یا، حقیقتس سٍتۍ}\n7. سارِنٕے چیزن ہُند پٲٹھۍ، سارِنٕے چیزن پیٹھ ایمان تھاوان، سارِنٕے چیزن ہٕنز وۅمید تھاوان تہٕ سارِنٕے چیزن ہُند برداش۔\n8.\\tخیرات چھہ نہ زانہہ ناکام سپدان: مگر اگر پیشین گویی آسہِ، تم گژھن ناکام۔ زبانہٕ آسہِ، تِم گژھن بند گژھن۔ اگر علم آسہِ، سہ گژھہِ ختم۔ {ناکام: Gr. غٲب}\n9. تکیازِ أسۍ چھہِ کُنہِ حدس تام زانان تہٕ کُنہِ حدس تام پیشن گویی کران۔\n10. مگر ییلہ سُہ کامل آسہِ، تیلہِ یُس کُنہِ حِصس منز آسہِ، سُہ گژھہِ ختم کرنہٕ۔ {Done away: Gr. vanish away}\n11.\\tییلہ بہٕ شُرۍ اوسس، میہ اوس شُرۍ سٕندِ حثیتہٕ کتھ کران، میہ اوس شُرۍ سٕندِ حثیتہٕ سمجُن، میہ اوس شُرۍ سٕندِ حثیتہٕ سونٛچان: مگر ییلہ بہٕ مرد بنیوو، میہ ترٲو بچہٕ چیز۔ {سونچ: یا، استدلال} {تھاوُن: Gr. vanish away}\n12.\\tفی الحال چھہِ اسۍ شیشہ منزہ وچھان، سیاہ پٲٹھۍ۔ مگر امہ پتہ بتھہِ: وۅنۍ چھیہ میہ کنہِ حدس تام پتاہ۔ مگر تیلہ گژھہِ میہ پتاہ تہِ زِ میہ تہِ چھہ زانان۔ {سیاہ پٲٹھۍ: Gr. in a riddle}\n13. تہٕ وۅنۍ چُھہ یِمن ترشوے ایمان، وۅمید، خیرات۔ مگر یمن منز چھہ ساروے کھوتہ بوڈ خیرات۔","1. خیرات پَتہٕ کٔرِو تہٕ روٗحٲنی {تحفہٕ} ہٕنز خواہش کٔرِو، بٔلکہِ یێلہِ تُہۍ پیشن گویی کٔرِو۔\n2. یُس {نامعلوم} زبانہِ منز کتھ کران چُھ، سُہ چُھ نہٕ انسانس سٍتـ̡ کتھ کران، بٔلکہِ چُھہ خدایس سٍتـ̡ کتھ کران، تکیازِ کانہہ تہِ انسان چُھہ نہٕ تس سٍتـ̡ سمجھان۔ بہرحال، روحس منز چھہ سہ اسرار بولان۔ {سمجُن: Gr. heareth}\n3. مگر یُس پیشن گویی کران چُھہ سُہ چُھ انسانن سٍتـ̡ تعلیم، نصیحت تہٕ تسلی دِنہٕ خٲطرٕ کتھ کران۔\n4. یُس {نامعلوم} زبانہِ منز کتھ کران چُھ، سُہ چُھ پانس سٍتـ̡ تعلیم دِوان۔ مگر یُس پیشن گویی کران چُھ، سُہ چُھ کلیساہس سٍتـ̡ تعلیم دِوان۔\n5. بہٕ چُھس یژھان زِ تۅہہ سارِوٕے کٔرِو زبانہٕ سٍتـ̡ کتھ کرنہٕ، بلکہ یێلہِ تہٕ یێلہِ نبوت کٔرِو سُہ یُس زبانہٕ سٍتـ̡ کتھ کران چُھ، سُہ چُھہ تشریح کٔرِتھ یُس کلیساہس ہٕندِس سٍتـ̡ برکت حٲصل سپدِ۔\n6. وۅنۍ یێلہِ بہٕ ژے نِش زبانہِ سٍتـ̡ کتھ کٔرِتھ، بہٕ کیا فٲیدٕ کٔرِتھ تہٕ بہٕ کُنہِ سٍتـ̡ کتھ کٔرِتھ یا علمہٕ سٍتـ̡ یا پیشن گویی سٍتـ̡ یا نظریہٕ سٍتـ̡ کتھ کرٕنـ̡ ۔\n7.\\tتہِ یِمن چیزن منز زندگی دِنہٕ واجنہِ آوازِ ورٲے تہِ آسہِ، چاہے تم آوازن منز کانہہ فرق دِوان چھہِ، یہ کتھہ پاٹھۍ گژھہِ معلوم زِ پایپہ کیا چھہ یا ہارپ۔ {آواز: یا، ٹیون}\n8.\\tیێلہِ یێلہِ بُرِ کانہہ غیر یقینی آواز دِیہِ، کُس کرِ پانس جنگہٕ خٲطرٕ تیار؟\n9.\\tیتھے پاٹھۍ چھہ تۅہہ زبانۍ سیتۍ آسان لفظ بولان یُس سہل سمجھنہ یوان چھہ، یہ کتھہ پاٹھۍ گژھہِ معلوم زِ کتھ کیا چھیہ وننہ آمژ۔ تِکیازِ تُہۍ کٔرِو ہوہس منز کتھ کرنہٕ۔ {آسان...: Gr. اہم}\n10.\\tدنیاہس منز آسہِ واریاہ قسمہ چہ آوازہ تہ یمن منز چھہ نہ کانہہ تہِ اشارہ ورٲے آسان۔\n11. تێلہِ اگر نہٕ بہٕ آوازِ ہُند معنی پتاہ آسہِ، بہٕ آسہٕ تٔمِس سٍتـ̡ یُس وحشی بولان چُھ، تہٕ یُس کتھ کرِ، سُہ آسہِ میانہِ خٲطرٕ وحشی۔\n12. یێلہِ تہِ چُھہ یێلہِ تہِ تُہۍ روٝحٲنی تحفہٕ سٍتـ̡ شوقہٕ تھاوان چھِو، یێلہِ تہٕ چُھہ کلیساہٕچ بُنیاد حٲصل کرنہٕ خٲطرٕ سٍتـ̡ {روحٲنی تحفہٕ: Gr. of Spirits}\n13. یُس {نامعلوم} زبانہِ منز کتھ کران چُھ، سُہ کرِ ترجمہٕ کرنہٕ خٲطرٕ دُعا کرنہٕ۔\n14. یێلہِ بہٕ کُنہِ {نامعلوم} زبانہِ منز دعا کران چُھس، میون روح چُھ دُعا کران، مگر میون فہم چُھ بے ثمر آسان۔\n15. تیلہِ کیا چُھ؟ بہٕ کَرٕ روحہٕ سٍتـ̡ دُعا، تہٕ بہٕ کَرٕ سٍتـ̡ دُعا تہٕ بہٕ گٮ۪وٕ روحہٕ سٍتـ̡ تہٕ بہٕ گٮ۪وٕ سٍتـ̡ سٍتـ̡ دُعا۔\n16.\\tنتہٕ ییلہ ژیہ روحس سٍتـ̡ برکت دِیہِ، یُس ناعلمن ہٕندِس کمرس منز روزان چُھ، سُہ کِتھہ کٔنۍ کرِ آمیٖن تُہند شُکریہ ادا کرنہٕ وِزِ سُہ چُھہ نہٕ تُہند کتھ سمجھان۔\n17.\\tتکیازِ ژے چُھہ پٔزۍ پٲٹھـ̡ شُکریہ ادا کران، مگر دۆیِم چُھہ نہٕ سٍتـ̡ دِنہٕ آم\n18. بہٕ چُھس خدایہ سُند شُکر ادا کران، بہٕ چُھس ژےٚ سارِوٕے کھۅتہٕ زیادٕ زبانہٕ سٍتـ̡ کتھ کران:\n19.\\tتوتہِ اوس کلیساہس منز میہ پانژھ لفظ پننہِ سمجھہٕ سٍتـ̡ بولان، یُتھ {پننہِ آوازہٕ} سٍتـ̡ بہٕ ہێکہٕ دَہ ساس لفظو کھوتہٕ زیادٕ باقین تہِ ہیچھناوٕنـ̡ ۔\n20. بھائیو، بچہٕ گژھِو نہٕ سمجھنس مَنٛز: یێلہِ تہٕ بد خواہشس سٍتـ̡ گژھِو بچہٕ، بٔلکہِ سمجھنس مَنٛز گژھہِ انسان۔ {مرد: Gr. کامل، یا، پۄختہٕ وٲنسہِ}\n21.\\tشریعتس مَنٛز چُھہ یہ لیکھنہٕ آمُت، باقین زبانن تہٕ باقین زبانن سٍتـ̡ بہٕ کَرٕ یِمن لُکن سٍتـ̡ کتھ کرنہٕ۔ تہٕ توتہِ یُس نہٕ تِم بوزان چھِ، خداوند چُھ وَنان۔\n22. لہٰذا چِھ زبانہٕ اکھ نشانہٕ، نہ تمن لوکن خٲطرٕ یُس ایمان تھاوان چُھ، بلکہ یمن لوکن خٲطرٕ چُھ نہٕ ایمان تھاون والن خٲطرٕ پیشن گوئی۔\n23. تێلہِ یێلہِ سورے کلیساہس اَکہِ جایہ یکجا گژھن تہٕ سارِوٕے زبانہٕ سٍتـ̡ کتھ کرنہٕ یِن، تہٕ یێلہِ سٍتـ̡ یێلہِ ی\n24.\\tمگر یێلہِ سارِنٕے پیشن گویی آسہِ، تہٕ یێلہِ کانہہ یُس نہٕ پژھ آسہِ، یا یێلہِ سُہ سارِنٕے سٍتـ̡ پۯاونہٕ آمُت چُھ، تێلہِ چُھہ سُہ سارِنٕے سٍتـ̡ پۯاونہٕ آمُت:\n25. تہٕ یِتھٕ پٲٹھۍ چھِ تٔمۍ سٕندِ دِلٕکۍ راز ظٲہر سپدان۔ تہٕ یِتھٕ پٲٹھـ̡ پى۪ٹھ\n26. تیلہٕ کیُتھ چُھہ بھائیو؟ ییلہ تم یکوٹہ سپدِو، تم منزٕ چھہ پریتھ اکس اکھ زبور، اکھ نظریہ، اکھ زبان، اکھ وحی تہ تشریح آسان۔ سٲری چیز گژھن تعلیم دِنہٕ خٲطرٕ کرنہٕ۔\n27.\\tاگر کانہہ انسان {نامعلوم} زبانۍ منز کتھ کرِ، {یہ گژھہِ} دۅیو منز، یا زیادہ کھوتہ زیادہ {by} تریہ منز، تہٕ {یہ} کتھ کرِ۔ تہٕ اکھ تشریح کرٕنۍ۔ {زٕ...: زٕ یا تریہ جملہٕ الگ الگ الگ کٔرِتھ}\n28. مگر اگر نہٕ ترجمہٕ کرن وول آسہِ، سُہ گژھہِ کلیساہس مَنٛز ژھۄپہٕ روزُن۔ تہٕ سُہ گژھہِ پانس سٍتـ̡ تہٕ خدایس سٍتـ̡ کتھ کرنہٕ۔\n29.\\tپیغمبرن گژھن زٕ تریہ کتھ تہٕ بییِس فیصلہ کرُن۔\n30.\\tاگر کانہہ چیز یُس بییِس پیٹھ بِہتھ آسہِ، گۅڈنچہ کُنہِ\n31. تِکیازِ تُہۍ سارِوٕے ہێکہِ اَکھ أکِس نِش پیشن گویی کٔرِتھ، یُتھ سارِنٕے ہێکہِ ہیچھناوُن، تہٕ سارِنٕے گژھن تسلی دِنہٕ۔\n32. تہٕ پیغمبرن ہٕندِ روحہٕ چِھ پیغمبرن ہٕندِس تابع آسان۔\n33. خدا چُھ نہٕ انتشار ہُند مصنف، بلکہ چُھ امنُک ، یِتھ کٔنۍ زَن مقدسن ہٕندِس سارِنٕے گرجا گھرن مَنٛز چُھ۔ {کنفیوژن: Gr. ہنگامہٕ، یا، بے چینی}\n34.\\tگرجا گھرن مَنٛز گژھن ژھۄپہٕ روزُن، تکیازِ تِمن چُھنہٕ کتھ کرنُک اجازت دِنہٕ۔ مگر {تمن چُھ} حکم دِنہٕ آمُت، یِتھ کٔنۍ شریعت تہِ چُھ وَنان۔\n35. تہٕ یێلہِ تِم کینہہ ہیٚچھِن، تێلہِ گژھن گرس مَنٛز پننین خاندارن پرژھن: کیازِ زنانن ہٕندِ خٲطرٕ چُھ کلیساہس مَنٛز کتھ کرٕنـ̡ شرمندگی۔\n36. کیا؟ خدایہِ سُند کلام آو ژے نِش نیرنہٕ؟ کِنہ یہ آو صرف ژےٚ؟\n37. اگر کانہہ انسان پانس پیغمبر یا روحٲنی سمجھان چُھ، سُہ گژھہِ تسلیم کرُن زِ یِم چیز بہٕ ژےٚ لیکھان چُھ، تم چِھ خداوند سٕندِ حکم۔\n38.\\tمگر اگر کانہہ انسان جاہل آسہِ، سُہ گژھہِ جہالت آسُن۔\n39. اَمہِ مۄکھٕ چھُ بٲے نبوت کرنُک طمع تہٕ زبانہٕ سٍتـ̡ کتھ کرنہٕ نِش منع کٔرِو۔\n40. سٲری چیز گژھن شائستگی سان تہٕ ترتیب سان کرنہٕ۔","1. اَمہِ علاوٕ، بھائیو، بہٕ چُھس ژےٚ سُہ انجیل اعلان کران یُس میہ تۅہہِ تبلیغ دِژمُت چُھ، یُس تہٕ یُس تہِ چُھہ تۅہہ حٲصل گومُت، تہٕ یتھ مَنٛز تُہۍ کھڑا چھِو۔\n2. ییمہِ سٍتـ̡ تہِ چُھہ تۅہہ نجات دِنہٕ آمُت، یێلہِ تہٕ یێلہِ تۅہہِ تۅہہِ تبلیغ کٔرمٕژ چھِ، یوتام نہٕ تۅہہ بیکار پژھ آسہِ۔ {رٔٹِو...: یا، تھپھ کٔرِتھ} {کیا: Gr. کتھ تقریر}\n3. تکیازِ میہ چُھہ سارِوٕے سٍتـ̡ سُہ تہِ دِژمُت یُس میہ تہِ میلہِ، کِتھہ پٲٹھـ̡ سپُد عیسیٰ مسیح صحیفہٕ مُطٲبق سانہِ گۅنہہ خٲطرٕ مُرد۔\n4. تہٕ سُہ آو دفن کرنہٕ، تہٕ صحیفہٕ مُطٲبق آو سُہ تریمہِ دۅہہ دُبارٕ زندٕ:\n5.\\tتہ یہ زِ سُہ آو سیفاسس سٍتـ̡ وُچھنہٕ، یُس بہن ہُند وُچھمُت:\n6. اَمہِ پتہٕ آو سُہ اَکی ساتہٕ پانژٕ ہتھ بٲے وُچھنہٕ۔ یمن منز چھہ زیادہ تر از تام روزان، مگر کینہہ چھہِ شوٚنگتھ گومت۔\n7. تمہ پتہ آو سہ جیمز وچھنہ۔ پَتہٕ سارِنٕے رسولَن ہٕندِس سٍتـ̡ ۔\n8. تہٕ ٲخٕر کار آو سُہ میہ سٍتۍ تہِ وُچھنہٕ، یُس وقتس سٍتۍ زامُت اوس۔ {اکھ...: یا، اکھ اسبورٹیو}\n9. کیازِ بہٕ چُھس رسولن منز سارِوٕے کھۄتہٕ کم، یُس نہٕ رسول وننہٕ خٲطرٕ میلان چُھ، کیازِ مے کٔر خدا سٕندِس کلیساہس ستاونہٕ۔\n10. مگر خدایہ سٕندِ فضل سٍتـ̡ چُھس بہٕ سُہ چُھس: تہٕ تٔمۍ سُند فضل یُس میہ دِنہٕ آمُت اوس، سُہ اوس نہٕ بیکار۔ مگر میہ کٔر یمن سارِنٕے کھۅتہٕ زیادٕ محنت، توتہِ بہٕ نہٕ، بلکہ خدایہ سُند فضل یُس میہ سٍتۍ اوس۔\n11.\\tتێلہِ چاہے یہ میہ آسہِ یا تِم، تێتھہ پاٹھۍ چھہِ أسۍ تبلیغ کران، تہٕ یێلہِ کٔرِو تۅہہ پژھ۔\n12. وۅنۍ یێلہِ عیسیٰ مسیح تبلیغ کرنہٕ ییہِ زِ سُہ چُھ مُردٕ سٍتـ̡ زندٕ سپدُن، تێلہِ کِتھہ پٲٹھـ̡ چُھہ تۅہہِ منزٕ کینہہ ونان زِ مُردن ہُند دُبارٕ چُھہ نہٕ زندٕ۔\n13. مگر یێلہِ نہٕ مُردن ہُند قیامتہٕ سپدِ، تیلہِ چُھہ نہٕ مسیح دُبارٕ دِنہٕ آمُت:\n14. تہٕ یێلہِ عیسیٰ مسیح زندٕ گژھہِ نہٕ، تیلہِ چُھہ سون تبلیغ بےکار، تہٕ تُہند ایمان تہِ چُھہ بیکار۔\n15. آ، تہٕ أسۍ چھِ خدایہ سٕندِ اپُز گواہ لبنہٕ آمٕتۍ۔ تکیازِ اسہِ چُھ خدایہ سٕنز گوٲہی دِژمٕژ زِ تٔمۍ کٔر مسیح زندٕ: یُس نہٕ تٔمۍ زندٕ کٔرِتھ، یێلہِ تہِ آسہِ نہٕ مُردن ہُند وُتھٕ دِنہٕ۔\n16. یێلہِ یێلہِ نہٕ مُردٕ دِنہٕ آمُت، تێلہِ چُھنہٕ مسیح زندٕ سپدُن:\n17. تہٕ یێلہِ عیسیٰ مسیح سُند پٲٹھـ̡ بێکار چُھہ، تێلہِ چُھہ تُہند ایمان بیکار۔ تُہۍ چھِو وُنہِ تہِ پننین گۅناہوں منز۔\n18.\\tتێلہِ چِھہ تِم تہِ یِم عیسیٰ مسیحس مَنٛز شوٚنگِتھ گٔژھان چھِ۔\n19. یێلہِ یێلہِ أسـ̡ عیسیٰ مسیحس سٍتـ̡ وۅمید چِھ، أسـ̡ سارِنٕے انسانن سٍتـ\n20. مگر وۅنۍ چُھ مسیح مُردٕ منزٕ زندٕ گومُت، {تہٕ} بنیوو تِمن ہُند گۄڈنیُک پھل۔\n21.\\tکیازِ انسان سٍتۍ {آو} موت، انسان سٍتۍ تہِ چھہ مرن ہند قیامت۔\n22. یِتھ کٔنۍ زَن آدمس سٍتـ̡ سٲری مران چِھ، تِتھے پٲٹھـ̡ یێلہِ مسیحس سٍتـ̡ سارِنٕے زِندٕ سپدِ۔\n23.\\tمگر پریتھ کانہہ انسان پننہِ ترتیبہِ منز: مسیح گۅڈنچہ پھلہٕ۔ امہِ پتہٕ یِم مسیح سٕندِ یِنہٕ وِزِ چھِ۔\n24.\\tتێلہِ چُھہ {یێلہِ} یێلہِ سُہ بادشٲہی خدایس حوالہٕ کرِ، حتیٰ کہ مٲلِس تہِ دِیہِ۔ ییٚلہ تٔمۍ تمام حکمرٲنی تہٕ تمام اختیار تہٕ اختیار ترٛاو۔\n25.\\tتکیازِ تس پزِ حکومت کرُن، یوتام نہ سُہ تمام دُشمن پننین قدمن تل تراوِ۔\n26.\\tٲخری دُشمن {یُس} گژھہِ تباہ سپدُن {سُہ} موت۔\n27.\\tکیازِ تٔمۍ چھُ سارِنٕے چیٖز پننِس قدمن تَل تھوومُت۔ مگر ییلہ سہ ونان چھہ زِ سٲری چیز چھہِ تمس تل تھاونہ آمت، یہ چھہ ظٲہر سپدان زِ سہ چھہ استثنیٰ تھاوان، یمۍ سٲری چیز پانس تل تراوۍ متۍ۔\n28. تہٕ یێلہِ سارِنٕے چیز أمِس تابع گژھِ، تیلہِ گژھہِ نیچو تہِ پانَے تٔمِس تابع یُس سارِنٕے چیز پانس تل تھاوِ، یُتھ خدایہ سارِنٕے سارِنٕے مَنٛز آسہِ۔\n29. نتہٕ کیا کرِ تِم یُس مُردن ہٕندِ خٲطرٕ بپتسمہ دِنہٕ آمُت چُھ، یێلہِ نہٕ مُردن ہٕندِ خٲطرٕ بپتسمہ دِنہٕ آمُت؟ تیلہِ کیازِ چھہِ تم مرن ہندِ خاطرہ بپتسمہ دِنہٕ یوان؟\n30.\\tتہِ کیازِ چھہِ اسہِ پریتھ ساعتہ خطرس منز کھڑا روزان؟\n31. بہٕ چُھس تُہنزِ خوشی سٍتـ̡ احتجاج کران یُس میہ مسیح عیسیٰ مسیحس سٍتـ̡ چُھہ روزان، بہٕ چُھس دۅہہٕ مران۔ {تُہُند: کینہہ پٔرِو، سانہِ}\n32.\\tیێلہِ یێلہِ یێلہِ میہ افسس سٍتـ̡ درندن سٍتـ̡ لڑان چُھ، تیلہِ کیا چُھہ میہ فٲیدٕ؟ أسۍ کھیوٚو چیٚو؛ تکیازِ پگاہ چھہِ اسۍ مران۔ {پتہٕ...: یا، مردن ہٕندِس طریقس پیٹھ کتھ کرٕن}\n33. دھوکہٕ گژھِ نہٕ: بد کلام چھُ اصل اخلاق خراب کران۔\n34.\\tنیکی ہٕندِس سٍتـ̡ بیدار گژھُن، تہٕ گۅناہ کرُن نہٕ۔ کینٛہن خٲطرٕ چُھنہٕ خدایہِ سُند علم: بہٕ چُھس ژےٚ شرمندگی ہٕنز کتھ کران۔\n35.\\tمگر کینہہ {انسان} ونن زِ مردہ کِتھہ پاٹھۍ چھہِ زندہ سپدان؟ تہٕ تِم کمہِ جسمس سٍتۍ چھِ یِوان؟\n36.\\tبیوقوف، یُس تہِ ژے وُچھان چھُ، سُہ چُھہ نہٕ زندٕ سپدان، مگر سُہ چُھہ مرُن:\n37.\\tتہٕ یُس تہٕ ژے ووت سُہ جسم یُس آسہِ، بلکہ چھُکھ کٕنُک یا بییہ کُنہِ دانہٕ سٍتـ̡ سٍتـ�\n38.\\tمگر خدا چُھ أمِس اکھ جسم دِوان یُس أمِس خۅش آسہِ، تہٕ پرٮ۪تھ أکِس بُلِس پنُن جسم۔\n39.\\tسارِوٕے ماز چُھ نہٕ اکوے ماز، مگر {اَتہِ} چُھ اَکھ {قٕسم} انسانہٕ سُند ماز، بیاکھ جانور سُند ماز، بیاکھ گاڈٕ سُند، {تہٕ} بیاکھ جاناوارن ہُند۔\n40. {تتہِ} تہِ چھِ آسمٲنی اجسام تہٕ زمینی اجسام تہِ: مگر آسمانی {چُھ} سُند جلال {چُھ} اکھ، تہٕ زمینی {چُھ} بیاکھ ۔\n41.\\tآفتابُک اکھ جلال تہٕ بیاکھ زوٗنہِ ہُند تہٕ بیاکھ ستارہ چھُ ستارن ہُند شان: تکیازِ {اَک} ستارٕ چُھ عظمتس منز {بییِس ستارہٕ سٍتـ̡ مختلف۔\n42.\\tیتھے پاٹھۍ چھہ مرن ہند قیامت۔ یہٕ چُھ بدعنوانی منٛز وونہٕ آمت۔ یہٕ چُھ بدعنوانی منٛز پرورش آمت کرنہٕ:\n43.\\tیہ چھُ بے عزتی سان وونہٕ آمُت۔ یہ چھہ عظمتس منز پرورش سپدان: یہ چھہ کمزوری منز وونہٕ آمت۔ یہٕ چُھ اقتدارس منٛز کھڑا کرنہٕ آمُت:\n44. یہ چُھ قدرتی جسم وونہٕ یوان۔ یہِ چُھ اکھ روٗحٲنی جسمہٕ پرورش کرنہٕ آمُت۔ اکھ قدرتی جسم چُھ، تہٕ اکھ روحٲنی جسم چُھ۔\n45. تہٕ یِتھے پٲٹھۍ چُھ لیکھنہٕ آمُت، گۅڈنِچ انسان آدم آو زندٕ روح بناونہٕ۔ ٲخری آدم {آو بناونہٕ} اکھ تیز روح ۔\n46.\\tمگر یہ {اوس} گۅڈہ یُس روحانی چھہ نہ بلکہ یُس فطری چھہ۔ تہٕ امہ پتہ یُس روحٲنی آسہِ۔\n47.\\tگۅڈنیُک انسان چھہ زمینہِ منز، زمینہِ پیٹھ: دۆیم انسان چھہ آسمانہ پیٹھہ خدا۔\n48.\\tیتھہ پاٹھۍ {چُھ} زمینہِ تہِ، تِتھۍ تہِ چھہِ زمینی: تہٕ یتھے پاٹھۍ {چھہ} آسمانی تہِ۔\n49. تہٕ یِتھٕ پٲٹھۍ أسۍ زمینہِ ہٕنز تصویر رٔٹِتھ چھِ، اسہِ تہِ رٔٹِتھ آسمانی سٕنز تصویر تہِ۔\n50. وۅنۍ چُھس بہٕ یہِ ونان زِ ماز تہٕ خون ہیکہِ نہٕ خدایہ سٕنزِ بادشٲہی ہُند وارث ٲسِتھ۔ نہ چھہ بدعنوانی وراثتس منز میلان۔\n51.\\tوچھ، میہ چھہ ژیہ اکھ اسرار ہاوان۔ اسہِ سارنے گژھن نہ شوٚنگتھ، مگر اسہِ سارنے بدلاونہ یِن،\n52.\\tأکِس لمحس منز، أچھ ٹپکاونہٕ سٍتـ̡ ٲخری ٹرمپ: تکیازِ ٹرمپٹ گژھہِ بجہِ، تہٕ مُردٕ یِن بُلاونہٕ یِن، تہٕ أسـ̡ بدلاونہٕ یِن۔\n53.\\tامہِ مۅکھہ گژھہِ بدعنوانی لاگُن، تہٕ یہ فانی گژھہِ لافانی آسن۔\n54.\\tتێلہِ ییلہ یہ بدکار بد عنوانی لٲگِتھ آسہِ، تہٕ یہ فانی لافانی لٲگِتھ آسہِ، تیلہِ گژھہِ سُہ قول پورٕ کرنہٕ یُس لیکھنہٕ آمُت چُھ، موت چُھ فتح سٍتـ̡ نِنہٕ آمُت۔\n55. اے موت، کتہِ چھُکھ تُہند ڈنگہ؟ اے قبر، تہنز فتح کتہِ چھیہ؟ {قبر: یا، جہنم}\n56. موتُک ڈنگہ {چُھ} گۅناہ۔ تہٕ گۅناہ ہٕنز طاقت چُھ شریعت۔\n57. مگر خدایہِ سُند شُکر ادا کرُن، یُس سانہِ آغہٕ عیسیٰ مسیح سٕندِ ذریعہٕ اسہِ فتح دِوان چُھ۔\n58. تێمہِ کِنۍ، میٲنۍ پیاری بٲے، تُہۍ گژھِو پٲٹھۍ، بے حرکت، ہمیشہٕ خداوند سٕنزِ کامہِ مَنٛز بٔرِتھ روزُن، یوتام تۅہہ زانان چھِو زِ تہنز محنت چُھہ نہٕ خداوند سٕندِس سٍتـ̡ بیکار۔","1. وۅنۍ چھُ مُقدسن ہٕندِ خٲطرٕ جمع کرنہٕ کِس سلسلس متعلق، یِتھٕ کٔنۍ مے گلتیہ کین کلیساہَن ہُند حکم دِژمُت، تۅہہ تہِ چُھہ تہِ۔\n2. ہفتہٕ کِس گۄڈنِکِس دۅہس پیٹھ گژھہِ تم منزٕ پرٮ۪تھ کانہہ أمِس نِش روزُن، یِتھ کٔنۍ {خدایہ} أمِس ترقی دِژمٕژ، یُس بہٕ یِنہٕ وِزِ گژھہِ نہٕ کانہہ اجتماع۔\n3. تہٕ ییلہ بہٕ یِیہ، یُس تہٕ ژے چِٹھہِ سٍتـ̡ منظوٗر کٔرِو، بہٕ سوزٕ تُہٕنز فراخ دٲری یروشلمس تام واتناونہٕ خٲطرٕ۔ {فراخدلی: Gr. تحفہٕ}\n4.\\tتہِ اگر میہ تہِ گژھہِ، تم گژھن میہ سٍتۍ۔\n5. وۅنۍ ییہ بہٕ ژے نِش، ییلہ بہٕ مقدونیہ کِنۍ نیرِ، تکیازِ بہٕ چُھس مقدونیہ کِنۍ نیران۔\n6. تہٕ یہ ہیکہِ ٲسِتھ زِ بہٕ روزٕ ژے سٍتـ̡ روزُن، تہٕ وندٕ روزُن، یێلہِ تہِ بہٕ یێلہِ تہِ بہٕ نیرِ۔\n7. کیازِ بہٕ وُچھٕ نہٕ وُنہِ تہِ وُچھان۔ مگر بہٕ چُھس یقین زِ اگر رب اجازت دِیہ، تہٕ بہٕ روزٕ ژےٚ سٍتۍ کینژس کالس روزُن۔\n8. مگر بہٕ روزٕ افسس تام پینتیکوسٹس تام۔\n9.\\tتکیازِ میانہِ خاطرہ چھہ اکھ بوٚڈ دروازہ تہٕ اثر یلہٕ آمُت، تہٕ {اتہِ} چھہِ واریاہ مخالف۔\n10. وۅنۍ یێلہِ تیموتھیس یِیہ، وُچھِو سُہ تہِ بێیہِ بێخوفہٕ سٍتـ̡ تہٕ یێلہِ سُہ چُھہ خداوند سٕنز کٲم کَران۔\n11.\\tتێلہِ گژھہِ نہ کانہہ تہِ انسان أمس حقارت کرُن، بلکہ کرُن أمس امن سان نیرُن، یُتھ سُہ میانہِ نِش یِنہٕ، کیازِ بہٕ چھُس تس بٲے سٍتـ̡ ژھانڈان۔\n12.\\tسٲنِس بٲے اپولوس سٍتـ̡ اوسُس بہٕ سٮ۪ٹھاہ یژھان زِ سُہ ییہ بٲے سٍتـ̡ ژے نِش یِن، مگر تٔمۍ سٕنز مرضی ٲس نہٕ امہِ وِزِ یِنہٕ۔ مگر سُہ ییہ تمہِ وِزِ ییلہ تس آسان وقت میلہِ۔\n13.\\tوُچھو، ایمانس مَنٛز کھڑا روزُن، مردن ہٕندۍ پٲٹھۍ، مضبوط روزُن۔\n14. پنٕنۍ سٲری چیز گژھن خیرات سٍتـ̡ کرنہٕ۔\n15. بہٕ چُھس ژےٚ التجا کٔرِتھ، بھائیو، (تُہۍ چھِو سٹیفناس سٕندِس گرس زانان زِ یہِ چُھ اخایاہُک گۄڈنیُک پھل، تہٕ {یہ} چُھہ تِمو پانہٕ مقدسن ہٕنزِ وزارتہِ ہٕندِس عادی گٔمٕتۍ،)\n16.\\tیُس تِمن ہٕندِس سٍتـ̡ تہٕ پرٮ۪تھ أکِس سٍتـ̡ یُس اسہِ سٍتـ̡ مدد کران چُھ، تہٕ محنت کرِ۔\n17. بہٕ چُھس سٹیفناس تہٕ فورٹونیٹس تہٕ اچیکس سٕندِ یِنہٕ سٍتـ̡ خۄش گومُت: یُس تۅہہِ ہٕندِ طرفہٕ کمی اوس تِمو دِژمُت۔\n18. تِمو چُھ میون تہٕ تُہُند روح تازٕ کورمُت، تێمہِ کِنۍ کرو تِمن ہُند اعتراف یِم یِمن ہٕندِس روحس سٍتـ̡ چھِ۔\n19. ایشیاہٕکۍ کلیساہٕ چِھ تۅہہِ سلام کران۔ عقیلہ تہٕ پرسکیلا چِھ تۅہہِ خداہس منز واریاہ سلام، کلیساہس سٍتـ̡ یُس تہندِس گرس مَنٛز چُھ۔\n20. سارِنٕے بٲے چھِ ژےٚ سلام کَران۔ اکھ أکِس کٔرِو مقدس بوسہ دِتھ سلام۔\n21. پولس سُند سلام۔\n22. یێلہِ کانہہ انسان عیسیٰ مسیح سٕندِ محبتس سٍتـ̡ محبت کران چُھ، سُہ گژھہِ اناتھیما مارانتھا آسُن۔\n23. سٲنـ̡ آغہٕ عیسیٰ مسیح سُند فضل {ہو} چُھہ توے سٍتـ̡ ۔\n24. میٲنۍ محبت، مسیح عیسیٰ مسیحس مَنٛز، تہٕ یێلہِ سٍتـ̡ چُھہ یێلہِ سٍتـ̡ سٍتـ̡ سٍتـ� آمین۔ «{کرنتھیس خٲطرٕ گۄڈنیُک خط} اوس فلپی پیٹھہٕ سٹیفناس تہٕ فورٹونیٹس تہٕ اکیکس تہٕ تیموتھیسن لیوکھمُت۔}»"];
